import type { BankQuestion } from "@/lib/bank";

/** Compound Interest (Quantitative Aptitude): 209 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-ci-1","question":"Compound interest on ₹10,000 at 10% per annum for 2 years is:","options":["₹2,000","₹2,100","₹2,200","₹2,310"],"answer":1,"explanation":"Amount = 10,000 × 1.1² = 12,100, so CI = ₹2,100. Shortcut: 2-year CI at 10% is 21% of the principal. ₹2,000 is the simple interest, which misses the interest on the first year's interest.","difficulty":"easy","questionHi":"₹10,000 पर 10% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹2,000","₹2,100","₹2,200","₹2,310"],"explanationHi":"मिश्रधन = 10,000 × 1.1² = 12,100, अतः चक्रवृद्धि ब्याज = ₹2,100। शॉर्टकट: 10% पर 2 वर्ष का चक्रवृद्धि ब्याज मूलधन का 21% होता है। ₹2,000 साधारण ब्याज है, जिसमें पहले वर्ष के ब्याज पर लगने वाला ब्याज छूट जाता है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-2","question":"The difference between CI and SI on ₹5,000 for 2 years at 10% is:","options":["₹25","₹50","₹100","₹500"],"answer":1,"explanation":"For 2 years, CI − SI = P(R/100)² = 5,000 × 0.01 = ₹50: it is just the interest earned on the first year's interest (₹500 × 10%). ₹500 is one year's interest, not the difference.","difficulty":"moderate","questionHi":"₹5,000 पर 2 वर्ष के लिए 10% की दर से चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर कितना होगा?","optionsHi":["₹25","₹50","₹100","₹500"],"explanationHi":"2 वर्ष के लिए CI − SI = P(R/100)² = 5,000 × 0.01 = ₹50। यह केवल पहले वर्ष के ब्याज (₹500 × 10%) पर मिलने वाला ब्याज है। ₹500 एक वर्ष का ब्याज है, अंतर नहीं।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-3","question":"₹8,000 at 5% compound interest for 2 years amounts to:","options":["₹8,400","₹8,800","₹8,820","₹9,000"],"answer":2,"explanation":"8,000 × 1.05² = 8,000 × 1.1025 = ₹8,820. ₹8,800 is the simple-interest amount, which forgets the ₹20 earned on the first year's ₹400 interest.","difficulty":"hard","questionHi":"₹8,000 पर 5% की दर से 2 वर्ष में चक्रवृद्धि ब्याज से मिश्रधन कितना होगा?","optionsHi":["₹8,400","₹8,800","₹8,820","₹9,000"],"explanationHi":"8,000 × 1.05² = 8,000 × 1.1025 = ₹8,820। ₹8,800 साधारण ब्याज वाला मिश्रधन है, जिसमें पहले वर्ष के ₹400 ब्याज पर मिलने वाले ₹20 छूट जाते हैं।","subtopic":"annual-compounding"},
  {"id":"quant-ci-4","question":"A sum doubles in 5 years at compound interest. In how many years will it become 8 times?","options":["10","15","20","40"],"answer":1,"explanation":"At compound interest the factor multiplies: 8 = 2³, so it takes 3 × 5 = 15 years. 20 years treats it like simple interest (doubling adds P every 5 years), and 40 years scales 8 × 5.","difficulty":"very-hard","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 5 वर्ष में दुगुनी हो जाती है। यह कितने वर्षों में 8 गुनी हो जाएगी?","optionsHi":["10","15","20","40"],"explanationHi":"चक्रवृद्धि ब्याज में गुणक गुणा होता जाता है: 8 = 2³, इसलिए 3 × 5 = 15 वर्ष लगेंगे। 20 वर्ष का उत्तर इसे साधारण ब्याज मान लेने पर आता है (दुगुना होने पर हर 5 वर्ष में P जुड़ता है), और 40 वर्ष 8 × 5 करने पर आता है।","subtopic":"times-the-sum"},
  {"id":"quant-ci-5","question":"The compound interest on ₹5,000 at 4% per annum for 2 years, compounded annually, is:","options":["₹408","₹420","₹400","₹416"],"answer":0,"explanation":"Amount = 5,000 × 1.04² = 5,000 × 1.0816 = ₹5,408, so CI = ₹408. ₹400 is the simple interest.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"₹5,000 पर 4% वार्षिक दर से 2 वर्ष का, वार्षिक रूप से संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹408","₹420","₹400","₹416"],"explanationHi":"मिश्रधन = 5,000 × 1.04² = 5,000 × 1.0816 = ₹5,408, अतः चक्रवृद्धि ब्याज = ₹408। ₹400 साधारण ब्याज है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-6","question":"₹8,000 at 10% per annum compounded half-yearly amounts in 1 year to:","options":["₹8,840","₹8,400","₹8,800","₹8,820"],"answer":3,"explanation":"Half-yearly rate 5% for 2 periods: 8,000 × 1.05² = 8,000 × 1.1025 = ₹8,820. ₹8,800 is the annual-compounding figure.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"₹8,000 पर 10% वार्षिक दर से अर्द्धवार्षिक संयोजित करने पर 1 वर्ष में मिश्रधन कितना होगा?","optionsHi":["₹8,840","₹8,400","₹8,800","₹8,820"],"explanationHi":"अर्द्धवार्षिक दर 5%, 2 अवधियाँ: 8,000 × 1.05² = 8,000 × 1.1025 = ₹8,820। ₹8,800 वार्षिक संयोजन वाला मान है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-7","question":"The compound interest on a sum for 2 years at 10% per annum is ₹420. The sum is:","options":["₹4,200","₹1,800","₹2,000","₹2,100"],"answer":2,"explanation":"CI for 2 years at 10% = 21% of the sum, so sum = 420/0.21 = ₹2,000.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर 10% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज ₹420 है। धनराशि कितनी है?","optionsHi":["₹4,200","₹1,800","₹2,000","₹2,100"],"explanationHi":"10% पर 2 वर्ष का चक्रवृद्धि ब्याज = मूलधन का 21%, अतः मूलधन = 420/0.21 = ₹2,000।","subtopic":"annual-compounding"},
  {"id":"quant-ci-8","question":"The compound interest on ₹8,000 for 1½ years at 10% per annum, compounded annually, is:","options":["₹1,320","₹1,200","₹1,261","₹1,240"],"answer":3,"explanation":"Amount = 8,000 × 1.10 × 1.05 = ₹9,240 (half a year's interest for the fractional period), so CI = ₹1,240. ₹1,261 wrongly compounds half-yearly for 3 periods.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"₹8,000 पर 10% वार्षिक दर से 1½ वर्ष का, वार्षिक रूप से संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹1,320","₹1,200","₹1,261","₹1,240"],"explanationHi":"मिश्रधन = 8,000 × 1.10 × 1.05 = ₹9,240 (भिन्नात्मक अवधि के लिए आधे वर्ष का ब्याज), अतः चक्रवृद्धि ब्याज = ₹1,240। ₹1,261 गलती से 3 अर्द्धवार्षिक अवधियों के लिए संयोजन कर देने पर आता है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-9","question":"The difference between compound interest and simple interest on ₹10,000 for 3 years at 10% per annum is:","options":["₹300","₹331","₹310","₹100"],"answer":2,"explanation":"SI = ₹3,000; CI = 10,000 × (1.331 − 1) = ₹3,310. Difference = ₹310. ₹100 is the 2-year difference.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"₹10,000 पर 10% वार्षिक दर से 3 वर्ष का चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर कितना होगा?","optionsHi":["₹300","₹331","₹310","₹100"],"explanationHi":"SI = ₹3,000; CI = 10,000 × (1.331 − 1) = ₹3,310। अंतर = ₹310। ₹100 2 वर्ष का अंतर है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-10","question":"At what rate of compound interest per annum does ₹1,600 become ₹1,936 in 2 years?","options":["11%","10%","9%","12%"],"answer":1,"explanation":"(1 + r/100)² = 1,936/1,600 = 1.21, so 1 + r/100 = 1.1 and r = 10%.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"चक्रवृद्धि ब्याज की कितनी वार्षिक दर से ₹1,600 की धनराशि 2 वर्ष में ₹1,936 हो जाएगी?","optionsHi":["11%","10%","9%","12%"],"explanationHi":"(1 + r/100)² = 1,936/1,600 = 1.21, अतः 1 + r/100 = 1.1 और r = 10%।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-11","question":"A sum amounts to ₹4,840 in 2 years and to ₹5,324 in 3 years at compound interest. The sum is:","options":["₹4,200","₹4,400","₹3,600","₹4,000"],"answer":3,"explanation":"Ratio of successive amounts = 5,324/4,840 = 1.1, so the rate is 10%. Sum = 4,840/1.21 = ₹4,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 2 वर्ष में ₹4,840 और 3 वर्ष में ₹5,324 हो जाती है। धनराशि कितनी है?","optionsHi":["₹4,200","₹4,400","₹3,600","₹4,000"],"explanationHi":"क्रमागत मिश्रधनों का अनुपात = 5,324/4,840 = 1.1, अतः दर 10% है। मूलधन = 4,840/1.21 = ₹4,000।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-12","question":"₹5,000 is invested at compound interest at 10% for the first year and 20% for the second year. The compound interest earned is:","options":["₹1,550","₹1,500","₹1,600","₹1,650"],"answer":2,"explanation":"Amount = 5,000 × 1.1 × 1.2 = ₹6,600, so CI = ₹1,600. Using an average rate of 15% for both years gives the wrong ₹1,612.5.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"₹5,000 को चक्रवृद्धि ब्याज पर निवेश किया जाता है, पहले वर्ष 10% और दूसरे वर्ष 20% की दर से। अर्जित चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹1,550","₹1,500","₹1,600","₹1,650"],"explanationHi":"मिश्रधन = 5,000 × 1.1 × 1.2 = ₹6,600, अतः चक्रवृद्धि ब्याज = ₹1,600। दोनों वर्षों के लिए औसत दर 15% लेने पर गलत उत्तर ₹1,612.5 आता है।","subtopic":"varying-rates"},
  {"id":"quant-ci-13","question":"The compound interest on ₹16,000 at 10% per annum compounded half-yearly for 1½ years is:","options":["₹2,522","₹2,480","₹2,400","₹2,520"],"answer":0,"explanation":"Three half-years at 5%: 16,000 × 1.05³ = 16,000 × 1.157625 = ₹18,522, so CI = ₹2,522.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"₹16,000 पर 10% वार्षिक दर से अर्द्धवार्षिक संयोजित करने पर 1½ वर्ष का चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹2,522","₹2,480","₹2,400","₹2,520"],"explanationHi":"5% की दर से तीन अर्द्धवार्षिक अवधियाँ: 16,000 × 1.05³ = 16,000 × 1.157625 = ₹18,522, अतः चक्रवृद्धि ब्याज = ₹2,522।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-14","question":"The difference between compound interest and simple interest on a sum for 2 years at 8% per annum is ₹32. The sum is:","options":["₹5,000","₹6,250","₹3,200","₹4,000"],"answer":0,"explanation":"For 2 years the difference = P(r/100)² = P × 0.0064 = 32, so P = ₹5,000.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"किसी धनराशि पर 8% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर ₹32 है। धनराशि कितनी है?","optionsHi":["₹5,000","₹6,250","₹3,200","₹4,000"],"explanationHi":"2 वर्ष के लिए अंतर = P(r/100)² = P × 0.0064 = 32, अतः P = ₹5,000।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-15","question":"The compound interest for the second year on a sum at 10% per annum is ₹1,210. The interest for the third year is:","options":["₹1,331","₹1,300","₹1,320","₹1,100"],"answer":0,"explanation":"Each year's interest is 1.1 times the previous year's: 1,210 × 1.1 = ₹1,331. (The sum is ₹11,000; ₹1,100 is the first-year interest.)","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर 10% वार्षिक दर से दूसरे वर्ष का चक्रवृद्धि ब्याज ₹1,210 है। तीसरे वर्ष का ब्याज कितना होगा?","optionsHi":["₹1,331","₹1,300","₹1,320","₹1,100"],"explanationHi":"प्रत्येक वर्ष का ब्याज पिछले वर्ष के ब्याज का 1.1 गुना होता है: 1,210 × 1.1 = ₹1,331। (मूलधन ₹11,000 है; ₹1,100 पहले वर्ष का ब्याज है।)","subtopic":"year-wise-interest"},
  {"id":"quant-ci-16","question":"A sum becomes 1.44 times itself in 2 years at compound interest. In how many years will it become 2.0736 times itself?","options":["5","4","3","6"],"answer":1,"explanation":"1.44 = 1.2², so the rate is 20% a year. 2.0736 = 1.44² = 1.2⁴, so 4 years. Choosing 3 confuses 2.0736 with 1.2³ = 1.728.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 2 वर्ष में अपनी 1.44 गुनी हो जाती है। यह कितने वर्षों में अपनी 2.0736 गुनी हो जाएगी?","optionsHi":["5","4","3","6"],"explanationHi":"1.44 = 1.2², अतः दर 20% वार्षिक है। 2.0736 = 1.44² = 1.2⁴, अतः 4 वर्ष। 3 चुनना 2.0736 को 1.2³ = 1.728 समझ लेने की भूल है।","subtopic":"times-the-sum"},
  {"id":"quant-ci-17","question":"A loan of ₹2,100 at 10% per annum compound interest is to be repaid in two equal annual instalments. Each instalment is:","options":["₹1,050","₹1,100","₹1,155","₹1,210"],"answer":3,"explanation":"Present value: x/1.1 + x/1.21 = 2,100. Multiply by 1.21: 1.1x + x = 2,541, so x = ₹1,210. Check: 1,100 + 1,000 = 2,100.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"10% वार्षिक चक्रवृद्धि ब्याज की दर पर ₹2,100 का ऋण दो समान वार्षिक किस्तों में चुकाया जाना है। प्रत्येक किस्त कितनी है?","optionsHi":["₹1,050","₹1,100","₹1,155","₹1,210"],"explanationHi":"वर्तमान मूल्य: x/1.1 + x/1.21 = 2,100। 1.21 से गुणा करने पर: 1.1x + x = 2,541, अतः x = ₹1,210। जाँच: 1,100 + 1,000 = 2,100।","subtopic":"annual-compounding"},
  {"id":"quant-ci-18","question":"The difference between compound interest and simple interest on a sum for 3 years at 10% per annum is ₹62. The sum is:","options":["₹2,100","₹2,000","₹1,800","₹6,200"],"answer":1,"explanation":"For 3 years the difference = P[(1.1)³ − 1 − 0.3] = 0.031P = 62, so P = ₹2,000.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर 10% वार्षिक दर से 3 वर्ष का चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर ₹62 है। धनराशि कितनी है?","optionsHi":["₹2,100","₹2,000","₹1,800","₹6,200"],"explanationHi":"3 वर्ष के लिए अंतर = P[(1.1)³ − 1 − 0.3] = 0.031P = 62, अतः P = ₹2,000।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-19","question":"₹8,000 is invested at 5% per annum compound interest. The interest for the third year alone is:","options":["₹420","₹441","₹400","₹462"],"answer":1,"explanation":"Amount at the start of year 3 = 8,000 × 1.05² = ₹8,820; third-year interest = 5% of 8,820 = ₹441.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"₹8,000 को 5% वार्षिक चक्रवृद्धि ब्याज की दर पर निवेश किया जाता है। केवल तीसरे वर्ष का ब्याज कितना होगा?","optionsHi":["₹420","₹441","₹400","₹462"],"explanationHi":"तीसरे वर्ष के आरंभ में राशि = 8,000 × 1.05² = ₹8,820; तीसरे वर्ष का ब्याज = 8,820 का 5% = ₹441।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-20","question":"The compound interest on ₹1,00,000 at 12% per annum compounded quarterly for 6 months is:","options":["₹6,000","₹6,180","₹6,120","₹6,090"],"answer":3,"explanation":"Quarterly rate 3% for 2 quarters: 1,00,000 × 1.03² = 1,06,090, so CI = ₹6,090. ₹6,000 is the simple interest.","difficulty":"very-hard","source":"SSC CGL · SBI PO","questionHi":"₹1,00,000 पर 12% वार्षिक दर से त्रैमासिक संयोजित करने पर 6 महीने का चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹6,000","₹6,180","₹6,120","₹6,090"],"explanationHi":"त्रैमासिक दर 3%, 2 तिमाहियाँ: 1,00,000 × 1.03² = 1,06,090, अतः चक्रवृद्धि ब्याज = ₹6,090। ₹6,000 साधारण ब्याज है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-21","question":"How many of the following statements are correct?\n1. For the first year, compound interest equals simple interest at the same rate.\n2. The difference between CI and SI for 3 years is P(r/100)².\n3. 10% per annum compounded half-yearly is equivalent to 10.5% per annum compounded annually.\n4. At compound interest, a sum that doubles in 3 years becomes 8 times in 12 years.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only 1 is true. 2 is false: for 3 years the difference is P(r/100)²(3 + r/100); P(r/100)² is the 2-year difference. 3 is false: 1.05² = 1.1025, i.e. 10.25%. 4 is false: 8 = 2³, so it takes 3 × 3 = 9 years, not 12.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. पहले वर्ष के लिए, समान दर पर चक्रवृद्धि ब्याज साधारण ब्याज के बराबर होता है।\n2. 3 वर्ष के लिए CI और SI का अंतर P(r/100)² होता है।\n3. 10% वार्षिक दर पर अर्द्धवार्षिक संयोजन, 10.5% वार्षिक दर पर वार्षिक संयोजन के समतुल्य है।\n4. चक्रवृद्धि ब्याज पर जो धनराशि 3 वर्ष में दुगुनी हो जाती है, वह 12 वर्ष में 8 गुनी हो जाती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चारों"],"explanationHi":"केवल 1 सही है। 2 गलत है: 3 वर्ष के लिए अंतर P(r/100)²(3 + r/100) होता है; P(r/100)² 2 वर्ष का अंतर है। 3 गलत है: 1.05² = 1.1025, अर्थात् 10.25%। 4 गलत है: 8 = 2³, इसलिए 3 × 3 = 9 वर्ष लगते हैं, 12 नहीं।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-22","question":"The simple interest on a sum at 5% per annum for 2 years is ₹1,000. The compound interest on the same sum at the same rate for 2 years is:","options":["₹1,050","₹1,025","₹1,100","₹1,000"],"answer":1,"explanation":"Sum = 1,000/0.10 = ₹10,000. CI = 10,000 × (1.05² − 1) = 10,000 × 0.1025 = ₹1,025.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर 5% वार्षिक दर से 2 वर्ष का साधारण ब्याज ₹1,000 है। उसी धनराशि पर उसी दर से 2 वर्ष का चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹1,050","₹1,025","₹1,100","₹1,000"],"explanationHi":"मूलधन = 1,000/0.10 = ₹10,000। CI = 10,000 × (1.05² − 1) = 10,000 × 0.1025 = ₹1,025।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-23","question":"₹20,000 is invested for 2 years at 10% per annum: in the first year interest is compounded annually, in the second year half-yearly. The amount at the end of 2 years is:","options":["₹24,255","₹24,200","₹24,310","₹24,000"],"answer":0,"explanation":"After year 1: 20,000 × 1.1 = ₹22,000. Year 2 at 5% per half-year: 22,000 × 1.05² = 22,000 × 1.1025 = ₹24,255.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"₹20,000 को 2 वर्ष के लिए 10% वार्षिक दर पर निवेश किया जाता है: पहले वर्ष ब्याज वार्षिक रूप से संयोजित होता है, दूसरे वर्ष अर्द्धवार्षिक। 2 वर्ष के अंत में मिश्रधन कितना होगा?","optionsHi":["₹24,255","₹24,200","₹24,310","₹24,000"],"explanationHi":"पहले वर्ष के बाद: 20,000 × 1.1 = ₹22,000। दूसरे वर्ष में प्रति अर्द्धवर्ष 5%: 22,000 × 1.05² = 22,000 × 1.1025 = ₹24,255।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-24","question":"On ₹10,000 at 20% per annum for 1 year, the compound interest compounded half-yearly exceeds that compounded annually by:","options":["₹210","₹200","₹100","₹50"],"answer":2,"explanation":"Annual: CI = ₹2,000. Half-yearly at 10% for 2 periods: 10,000 × 0.21 = ₹2,100. Difference = ₹100.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"₹10,000 पर 20% वार्षिक दर से 1 वर्ष में अर्द्धवार्षिक संयोजित चक्रवृद्धि ब्याज, वार्षिक संयोजित चक्रवृद्धि ब्याज से कितना अधिक होगा?","optionsHi":["₹210","₹200","₹100","₹50"],"explanationHi":"वार्षिक: CI = ₹2,000। 10% पर 2 अवधियों के लिए अर्द्धवार्षिक: 10,000 × 0.21 = ₹2,100। अंतर = ₹100।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-25","question":"What amount will ₹4,000 become in 2 years at 5% per annum compound interest, compounded annually?","options":["₹4,400","₹4,410","₹4,420","₹4,200"],"answer":1,"explanation":"A = 4,000 × (1.05)² = 4,000 × 1.1025 = ₹4,410. ₹4,400 is the simple-interest amount.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"₹4,000 की धनराशि 5% वार्षिक चक्रवृद्धि ब्याज की दर से, वार्षिक रूप से संयोजित, 2 वर्ष में कितनी हो जाएगी?","optionsHi":["₹4,400","₹4,410","₹4,420","₹4,200"],"explanationHi":"A = 4,000 × (1.05)² = 4,000 × 1.1025 = ₹4,410। ₹4,400 साधारण ब्याज वाला मिश्रधन है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-26","question":"What is the compound interest on ₹12,500 at 8% per annum for 2 years, compounded annually?","options":["₹2,080","₹2,000","₹2,160","₹1,080"],"answer":0,"explanation":"A = 12,500 × (1.08)² = 12,500 × 1.1664 = 14,580. CI = 14,580 − 12,500 = ₹2,080. ₹2,000 is simple interest.","difficulty":"moderate","source":"SSC CGL","questionHi":"₹12,500 पर 8% वार्षिक दर से 2 वर्ष का, वार्षिक रूप से संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹2,080","₹2,000","₹2,160","₹1,080"],"explanationHi":"A = 12,500 × (1.08)² = 12,500 × 1.1664 = 14,580। CI = 14,580 − 12,500 = ₹2,080। ₹2,000 साधारण ब्याज है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-27","question":"A sum amounts to ₹13,310 in 3 years at 10% per annum compound interest. What is the sum?","options":["₹10,238","₹9,317","₹11,000","₹10,000"],"answer":3,"explanation":"P = 13,310 ÷ (1.1)³ = 13,310 ÷ 1.331 = ₹10,000. ₹10,238 divides by 1.3 (simple interest) instead.","difficulty":"moderate","source":"SSC CGL","questionHi":"कोई धनराशि 10% वार्षिक चक्रवृद्धि ब्याज की दर से 3 वर्ष में ₹13,310 हो जाती है। धनराशि कितनी है?","optionsHi":["₹10,238","₹9,317","₹11,000","₹10,000"],"explanationHi":"P = 13,310 ÷ (1.1)³ = 13,310 ÷ 1.331 = ₹10,000। ₹10,238 में (साधारण ब्याज की तरह) 1.3 से भाग दिया गया है।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-28","question":"The compound interest on a sum for 2 years at 12.5% per annum is ₹1,530. What is the simple interest on the same sum at the same rate for 2 years?","options":["₹1,500","₹1,360","₹1,440","₹1,530"],"answer":2,"explanation":"12.5% = 1/8, so CI factor = (9/8)² − 1 = 17/64. P = 1,530 × 64/17 = 5,760. SI = 5,760 × 12.5% × 2 = ₹1,440.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"किसी धनराशि पर 12.5% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज ₹1,530 है। उसी धनराशि पर उसी दर से 2 वर्ष का साधारण ब्याज कितना होगा?","optionsHi":["₹1,500","₹1,360","₹1,440","₹1,530"],"explanationHi":"12.5% = 1/8, अतः CI गुणक = (9/8)² − 1 = 17/64। P = 1,530 × 64/17 = 5,760। SI = 5,760 × 12.5% × 2 = ₹1,440।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-29","question":"A town of 50,000 grows by 10% in the first year, falls by 10% in the second year and grows by 20% in the third year. What is the population after 3 years?","options":["60,000","59,400","59,000","60,500"],"answer":1,"explanation":"50,000 × 1.1 × 0.9 × 1.2 = 59,400. Adding the rates (+20%) gives 60,000, which ignores compounding.","difficulty":"hard","source":"SSC CGL","questionHi":"50,000 की जनसंख्या वाले एक कस्बे में पहले वर्ष 10% की वृद्धि होती है, दूसरे वर्ष 10% की कमी होती है और तीसरे वर्ष 20% की वृद्धि होती है। 3 वर्ष बाद जनसंख्या कितनी होगी?","optionsHi":["60,000","59,400","59,000","60,500"],"explanationHi":"50,000 × 1.1 × 0.9 × 1.2 = 59,400। दरों को जोड़ने (+20%) पर 60,000 आता है, जिसमें चक्रवृद्धि की अनदेखी हो जाती है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-30","question":"A machine worth ₹1,50,000 today depreciates at 20% per annum. What will it be worth after 3 years?","options":["₹76,800","₹60,000","₹96,000","₹81,920"],"answer":0,"explanation":"Value = 1,50,000 × (0.8)³ = 1,50,000 × 0.512 = ₹76,800. ₹60,000 subtracts 60% simply; ₹96,000 is the value after 2 years.","difficulty":"hard","source":"SSC CGL","questionHi":"आज ₹1,50,000 मूल्य की एक मशीन का मूल्य 20% वार्षिक दर से घटता है। 3 वर्ष बाद उसका मूल्य कितना होगा?","optionsHi":["₹76,800","₹60,000","₹96,000","₹81,920"],"explanationHi":"मूल्य = 1,50,000 × (0.8)³ = 1,50,000 × 0.512 = ₹76,800। ₹60,000 सीधे 60% घटाने से आता है; ₹96,000 2 वर्ष बाद का मूल्य है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-31","question":"A loan of ₹6,620 at 10% per annum compound interest is to be repaid in three equal annual instalments. What is each instalment?","options":["₹2,428","₹2,200","₹2,420","₹2,662"],"answer":3,"explanation":"x/1.1 + x/1.21 + x/1.331 = 6,620 → x(1.21 + 1.1 + 1)/1.331 = 6,620 → x × 3.31/1.331 = 6,620 → x = 2,000 × 1.331 = ₹2,662.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"10% वार्षिक चक्रवृद्धि ब्याज की दर पर ₹6,620 का ऋण तीन समान वार्षिक किस्तों में चुकाया जाना है। प्रत्येक किस्त कितनी है?","optionsHi":["₹2,428","₹2,200","₹2,420","₹2,662"],"explanationHi":"x/1.1 + x/1.21 + x/1.331 = 6,620 → x(1.21 + 1.1 + 1)/1.331 = 6,620 → x × 3.31/1.331 = 6,620 → x = 2,000 × 1.331 = ₹2,662।","subtopic":"annual-compounding"},
  {"id":"quant-ci-32","question":"The difference between compound interest and simple interest on a sum for 3 years at 5% per annum is ₹122. What is the sum?","options":["₹16,264","₹48,800","₹16,000","₹15,000"],"answer":2,"explanation":"For 3 years, CI − SI = P(3r²/100² + r³/100³) = P(0.0075 + 0.000125) = 0.007625P = 122, so P = ₹16,000. Using the 2-year formula Pr²/100² gives ₹48,800.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"किसी धनराशि पर 5% वार्षिक दर से 3 वर्ष का चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर ₹122 है। धनराशि कितनी है?","optionsHi":["₹16,264","₹48,800","₹16,000","₹15,000"],"explanationHi":"3 वर्ष के लिए CI − SI = P(3r²/100² + r³/100³) = P(0.0075 + 0.000125) = 0.007625P = 122, अतः P = ₹16,000। 2 वर्ष का सूत्र Pr²/100² लगाने पर ₹48,800 आता है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-33","question":"A sum amounts to ₹8,820 in 2 years at 5% per annum compound interest. What simple interest would the same sum earn in 4 years at the same rate?","options":["₹1,764","₹1,600","₹1,722","₹1,640"],"answer":1,"explanation":"P = 8,820 ÷ 1.1025 = 8,000. SI = 8,000 × 5% × 4 = ₹1,600. ₹1,764 takes 20% of 8,820 instead of 8,000.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"कोई धनराशि 5% वार्षिक चक्रवृद्धि ब्याज की दर से 2 वर्ष में ₹8,820 हो जाती है। वही धनराशि उसी दर से 4 वर्ष में कितना साधारण ब्याज अर्जित करेगी?","optionsHi":["₹1,764","₹1,600","₹1,722","₹1,640"],"explanationHi":"P = 8,820 ÷ 1.1025 = 8,000। SI = 8,000 × 5% × 4 = ₹1,600। ₹1,764 में 8,000 के बजाय 8,820 का 20% लिया गया है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-34","question":"₹3,903 is divided between A and B so that A's share after 7 years equals B's share after 9 years, at 4% per annum compound interest. What is A's share?","options":["₹2,028","₹1,875","₹2,000","₹1,950"],"answer":0,"explanation":"A(1.04)⁷ = B(1.04)⁹ → A/B = (1.04)² = 676/625. Total 1,301 parts = 3,903, so one part = 3. A = 676 × 3 = ₹2,028, B = ₹1,875 (the trap if the ratio is inverted).","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"₹3,903 को A और B में इस प्रकार बाँटा जाता है कि 4% वार्षिक चक्रवृद्धि ब्याज की दर पर 7 वर्ष बाद A का हिस्सा 9 वर्ष बाद B के हिस्से के बराबर हो। A का हिस्सा कितना है?","optionsHi":["₹2,028","₹1,875","₹2,000","₹1,950"],"explanationHi":"A(1.04)⁷ = B(1.04)⁹ → A/B = (1.04)² = 676/625। कुल 1,301 भाग = 3,903, अतः एक भाग = 3। A = 676 × 3 = ₹2,028, B = ₹1,875 (अनुपात उलट देने पर यही जाल बनता है)।","subtopic":"annual-compounding"},
  {"id":"quant-ci-35","question":"What will ₹6,250 amount to in 2 years at 8% per annum compound interest, compounded annually?","options":["₹7,200","₹7,290","₹7,300","₹7,250"],"answer":1,"explanation":"A = 6,250 × 1.08² = 6,250 × 1.1664 = ₹7,290. ₹7,250 is the simple-interest amount.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"₹6,250 की धनराशि 8% वार्षिक चक्रवृद्धि ब्याज की दर से, वार्षिक रूप से संयोजित, 2 वर्ष में कितनी हो जाएगी?","optionsHi":["₹7,200","₹7,290","₹7,300","₹7,250"],"explanationHi":"A = 6,250 × 1.08² = 6,250 × 1.1664 = ₹7,290। ₹7,250 साधारण ब्याज वाला मिश्रधन है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-36","question":"What is the effective annual rate of interest for 10% per annum compounded half-yearly?","options":["10.5%","10.25%","10%","20%"],"answer":1,"explanation":"Two half-years at 5%: 1.05² = 1.1025, i.e. an effective 10.25% a year.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"10% वार्षिक दर पर अर्द्धवार्षिक संयोजित ब्याज की प्रभावी वार्षिक दर कितनी होगी?","optionsHi":["10.5%","10.25%","10%","20%"],"explanationHi":"5% की दर से दो अर्द्धवार्षिक अवधियाँ: 1.05² = 1.1025, अर्थात् प्रभावी वार्षिक दर 10.25%।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-37","question":"What will ₹1,000 amount to in 3 years at 20% per annum compound interest, compounded annually?","options":["₹1,800","₹1,680","₹1,728","₹1,600"],"answer":2,"explanation":"A = 1,000 × 1.2³ = 1,000 × 1.728 = ₹1,728. ₹1,600 is the simple-interest amount.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"₹1,000 की धनराशि 20% वार्षिक चक्रवृद्धि ब्याज की दर से, वार्षिक रूप से संयोजित, 3 वर्ष में कितनी हो जाएगी?","optionsHi":["₹1,800","₹1,680","₹1,728","₹1,600"],"explanationHi":"A = 1,000 × 1.2³ = 1,000 × 1.728 = ₹1,728। ₹1,600 साधारण ब्याज वाला मिश्रधन है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-38","question":"At 15% per annum compound interest, what is the ratio of the interest for the second year to the interest for the first year?","options":["1 : 1","6 : 5","20 : 23","23 : 20"],"answer":3,"explanation":"The second year's interest is earned on 1.15 times the principal, so the ratio is 1.15 : 1 = 23 : 20.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"15% वार्षिक चक्रवृद्धि ब्याज की दर पर दूसरे वर्ष के ब्याज और पहले वर्ष के ब्याज का अनुपात कितना होगा?","optionsHi":["1 : 1","6 : 5","20 : 23","23 : 20"],"explanationHi":"दूसरे वर्ष का ब्याज मूलधन के 1.15 गुने पर मिलता है, अतः अनुपात 1.15 : 1 = 23 : 20 है।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-39","question":"A machine loses 10% of its value in the first year and 20% of its value in the second year. It is now worth ₹36,000. What was its original value?","options":["₹52,000","₹50,000","₹48,000","₹51,429"],"answer":1,"explanation":"Value now = V × 0.9 × 0.8 = 0.72V = 36,000, so V = ₹50,000. ₹51,429 treats the losses as a single 30% fall.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक मशीन पहले वर्ष में अपने मूल्य का 10% और दूसरे वर्ष में अपने मूल्य का 20% खो देती है। अब उसका मूल्य ₹36,000 है। उसका मूल मूल्य कितना था?","optionsHi":["₹52,000","₹50,000","₹48,000","₹51,429"],"explanationHi":"वर्तमान मूल्य = V × 0.9 × 0.8 = 0.72V = 36,000, अतः V = ₹50,000। ₹51,429 में दोनों कमियों को एक साथ 30% की कमी मान लिया गया है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-40","question":"The population of a village decreases by 5% every year. It is 72,200 now. What was it 2 years ago?","options":["80,222","76,000","80,000","79,420"],"answer":2,"explanation":"P × 0.95² = 0.9025P = 72,200, so P = 80,000. Adding 10% to 72,200 (79,420) is the slip.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक गाँव की जनसंख्या प्रतिवर्ष 5% घटती है। वह अब 72,200 है। 2 वर्ष पहले यह कितनी थी?","optionsHi":["80,222","76,000","80,000","79,420"],"explanationHi":"P × 0.95² = 0.9025P = 72,200, अतः P = 80,000। 72,200 में 10% जोड़ना (79,420) सामान्य भूल है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-41","question":"In how many years will ₹2,000 amount to ₹2,662 at 10% per annum compound interest?","options":["3.5 years","2 years","4 years","3 years"],"answer":3,"explanation":"2,662/2,000 = 1.331 = 1.1³, so exactly 3 years. 3.5 years comes from estimating with simple interest, which understates the growth.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"10% वार्षिक चक्रवृद्धि ब्याज की दर पर ₹2,000 की धनराशि कितने वर्षों में ₹2,662 हो जाएगी?","optionsHi":["3.5 वर्ष","2 वर्ष","4 वर्ष","3 वर्ष"],"explanationHi":"2,662/2,000 = 1.331 = 1.1³, अतः ठीक 3 वर्ष। 3.5 वर्ष का उत्तर साधारण ब्याज से अनुमान लगाने पर आता है, जिसमें वृद्धि कम आँकी जाती है।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-42","question":"A man invests ₹10,000 at 10% per annum compound interest and withdraws ₹2,000 at the end of each year (after interest is added). What is his balance at the end of 2 years?","options":["₹8,100","₹7,700","₹8,000","₹7,900"],"answer":3,"explanation":"Year 1: 11,000 − 2,000 = ₹9,000. Year 2: 9,900 − 2,000 = ₹7,900.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"एक व्यक्ति ₹10,000 को 10% वार्षिक चक्रवृद्धि ब्याज पर निवेश करता है और प्रत्येक वर्ष के अंत में (ब्याज जुड़ने के बाद) ₹2,000 निकाल लेता है। 2 वर्ष के अंत में उसकी शेष राशि कितनी होगी?","optionsHi":["₹8,100","₹7,700","₹8,000","₹7,900"],"explanationHi":"पहला वर्ष: 11,000 − 2,000 = ₹9,000। दूसरा वर्ष: 9,900 − 2,000 = ₹7,900।","subtopic":"annual-compounding"},
  {"id":"quant-ci-43","question":"₹A invested for 2 years and ₹B invested for 3 years, both at 10% per annum compound interest, give equal amounts. What is A : B?","options":["11 : 10","2 : 3","121 : 100","10 : 11"],"answer":0,"explanation":"Equal amounts mean A × 1.1² = B × 1.1³, so A/B = 1.1 = 11 : 10; A must be larger because it grows for one year less. 10 : 11 inverts this, and 121 : 100 uses 1.1² instead of 1.1.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"₹A को 2 वर्ष के लिए और ₹B को 3 वर्ष के लिए, दोनों को 10% वार्षिक चक्रवृद्धि ब्याज की दर पर निवेश करने पर समान मिश्रधन मिलता है। A : B कितना है?","optionsHi":["11 : 10","2 : 3","121 : 100","10 : 11"],"explanationHi":"मिश्रधन बराबर होने का अर्थ है A × 1.1² = B × 1.1³, अतः A/B = 1.1 = 11 : 10; A बड़ा होना चाहिए क्योंकि वह एक वर्ष कम बढ़ता है। 10 : 11 इसे उलट देता है, और 121 : 100 में 1.1 की जगह 1.1² लिया गया है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-44","question":"At what rate of simple interest per annum will a sum earn the same interest in 2 years as it does at 10% per annum compound interest, compounded annually?","options":["10.5%","10%","11%","10.25%"],"answer":0,"explanation":"CI for 2 years at 10% = 21% of the sum. SI of 21% in 2 years needs a rate of 10.5%.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"साधारण ब्याज की कितनी वार्षिक दर से कोई धनराशि 2 वर्ष में उतना ही ब्याज अर्जित करेगी जितना 10% वार्षिक दर से, वार्षिक रूप से संयोजित, चक्रवृद्धि ब्याज पर अर्जित करती है?","optionsHi":["10.5%","10%","11%","10.25%"],"explanationHi":"10% पर 2 वर्ष का चक्रवृद्धि ब्याज = मूलधन का 21%। 2 वर्ष में 21% साधारण ब्याज के लिए दर 10.5% चाहिए।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-45","question":"A sum at compound interest amounts to ₹6,050 in 2 years, and the interest for the third year alone is ₹605. What is the sum?","options":["₹5,445","₹5,500","₹5,000","₹4,840"],"answer":2,"explanation":"Third-year interest is earned on the 2-year amount: 605/6,050 = 10%. So P × 1.21 = 6,050 and P = ₹5,000.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 2 वर्ष में ₹6,050 हो जाती है, और केवल तीसरे वर्ष का ब्याज ₹605 है। धनराशि कितनी है?","optionsHi":["₹5,445","₹5,500","₹5,000","₹4,840"],"explanationHi":"तीसरे वर्ष का ब्याज 2 वर्ष के मिश्रधन पर मिलता है: 605/6,050 = 10%। अतः P × 1.21 = 6,050 और P = ₹5,000।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-46","question":"The simple interest on a sum for 2 years is ₹960, and the compound interest on it for the same period and rate is ₹1,008. What is the sum?","options":["₹5,280","₹9,600","₹4,800","₹4,000"],"answer":2,"explanation":"One year's SI = ₹480. The extra ₹48 is interest on ₹480 for one year, so R = 48/480 = 10% and P = 480/0.10 = ₹4,800.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"किसी धनराशि पर 2 वर्ष का साधारण ब्याज ₹960 है, और उसी अवधि व उसी दर पर चक्रवृद्धि ब्याज ₹1,008 है। धनराशि कितनी है?","optionsHi":["₹5,280","₹9,600","₹4,800","₹4,000"],"explanationHi":"एक वर्ष का SI = ₹480। अतिरिक्त ₹48 एक वर्ष के लिए ₹480 पर ब्याज है, अतः R = 48/480 = 10% और P = 480/0.10 = ₹4,800।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-47","question":"A machine worth ₹1,00,000 depreciates by 10% a year for the first 2 years and by 20% a year after that. What is it worth after 4 years?","options":["₹50,000","₹48,600","₹51,840","₹52,488"],"answer":2,"explanation":"Value = 1,00,000 × 0.9² × 0.8² = 1,00,000 × 0.81 × 0.64 = ₹51,840. Subtracting 10 + 10 + 20 + 20 = 60% gives the simple-depreciation figure.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"₹1,00,000 मूल्य की एक मशीन के मूल्य में पहले 2 वर्षों तक प्रतिवर्ष 10% और उसके बाद प्रतिवर्ष 20% की कमी होती है। 4 वर्ष बाद उसका मूल्य कितना होगा?","optionsHi":["₹50,000","₹48,600","₹51,840","₹52,488"],"explanationHi":"मूल्य = 1,00,000 × 0.9² × 0.8² = 1,00,000 × 0.81 × 0.64 = ₹51,840। 10 + 10 + 20 + 20 = 60% घटाने पर साधारण ह्रास वाला मान आता है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-48","question":"What is the compound interest on ₹8,000 for 2 years 3 months at 10% per annum, compounded annually (simple interest for the part of a year)?","options":["₹1,800","₹1,983","₹2,000","₹1,922"],"answer":3,"explanation":"Amount = 8,000 × 1.1² × (1 + 0.10 × 3/12) = 9,680 × 1.025 = ₹9,922, so CI = ₹1,922.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"₹8,000 पर 10% वार्षिक दर से 2 वर्ष 3 माह का, वार्षिक रूप से संयोजित (वर्ष के भाग के लिए साधारण ब्याज), चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹1,800","₹1,983","₹2,000","₹1,922"],"explanationHi":"मिश्रधन = 8,000 × 1.1² × (1 + 0.10 × 3/12) = 9,680 × 1.025 = ₹9,922, अतः CI = ₹1,922।","subtopic":"annual-compounding"},
  {"id":"quant-ci-49","question":"The population of a town is 62,500. Every year the birth rate is 6% and the death rate is 2% of the population at the start of that year. What will the population be after 2 years?","options":["67,600","70,225","65,000","67,500"],"answer":0,"explanation":"Net growth = 4% a year compounded: 62,500 × 1.04² = 62,500 × 1.0816 = 67,600. 67,500 adds 8% simply.","difficulty":"hard","source":"RRB NTPC · SSC CGL","questionHi":"एक कस्बे की जनसंख्या 62,500 है। प्रत्येक वर्ष जन्म दर उस वर्ष के आरंभ की जनसंख्या का 6% और मृत्यु दर 2% है। 2 वर्ष बाद जनसंख्या कितनी होगी?","optionsHi":["67,600","70,225","65,000","67,500"],"explanationHi":"शुद्ध वृद्धि = 4% प्रतिवर्ष, चक्रवृद्धि रूप में: 62,500 × 1.04² = 62,500 × 1.0816 = 67,600। 67,500 में 8% साधारण रूप से जोड़ा गया है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-50","question":"A loan taken at 10% per annum compound interest is cleared by paying ₹5,500 at the end of the first year and ₹6,050 at the end of the second year. What was the loan?","options":["₹11,550","₹10,000","₹9,500","₹10,500"],"answer":1,"explanation":"Present value = 5,500/1.1 + 6,050/1.21 = 5,000 + 5,000 = ₹10,000. ₹11,550 just adds the payments.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"10% वार्षिक चक्रवृद्धि ब्याज पर लिया गया एक ऋण पहले वर्ष के अंत में ₹5,500 और दूसरे वर्ष के अंत में ₹6,050 चुकाकर चुकता किया जाता है। ऋण कितना था?","optionsHi":["₹11,550","₹10,000","₹9,500","₹10,500"],"explanationHi":"वर्तमान मूल्य = 5,500/1.1 + 6,050/1.21 = 5,000 + 5,000 = ₹10,000। ₹11,550 में केवल भुगतानों को जोड़ दिया गया है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-51","question":"At 12.5% per annum, the compound interest on a sum for 2 years exceeds the simple interest by ₹75. What is the compound interest?","options":["₹1,200","₹1,350","₹1,275","₹1,125"],"answer":2,"explanation":"Difference = P(1/8)² = P/64 = 75, so P = ₹4,800. CI = 4,800 × [(9/8)² − 1] = 4,800 × 17/64 = ₹1,275. ₹1,200 is the SI.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"12.5% वार्षिक दर पर किसी धनराशि का 2 वर्ष का चक्रवृद्धि ब्याज साधारण ब्याज से ₹75 अधिक है। चक्रवृद्धि ब्याज कितना है?","optionsHi":["₹1,200","₹1,350","₹1,275","₹1,125"],"explanationHi":"अंतर = P(1/8)² = P/64 = 75, अतः P = ₹4,800। CI = 4,800 × [(9/8)² − 1] = 4,800 × 17/64 = ₹1,275। ₹1,200 साधारण ब्याज है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-52","question":"The compound interest on a sum is ₹1,320 for the second year and ₹1,452 for the third year. What is the sum?","options":["₹12,000","₹11,000","₹10,000","₹13,200"],"answer":0,"explanation":"Rate = (1,452 − 1,320)/1,320 = 10%. Second-year interest = P × 1.1 × 0.1 = 1,320, so P = ₹12,000. ₹13,200 is the amount after the first year.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"किसी धनराशि पर दूसरे वर्ष का चक्रवृद्धि ब्याज ₹1,320 और तीसरे वर्ष का ₹1,452 है। धनराशि कितनी है?","optionsHi":["₹12,000","₹11,000","₹10,000","₹13,200"],"explanationHi":"दर = (1,452 − 1,320)/1,320 = 10%। दूसरे वर्ष का ब्याज = P × 1.1 × 0.1 = 1,320, अतः P = ₹12,000। ₹13,200 पहले वर्ष के बाद का मिश्रधन है।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-53","question":"How many of the following statements are correct?\n1. At the same nominal rate, half-yearly compounding gives more interest in a year than annual compounding.\n2. The difference between CI and SI for 2 years is P(r/100)².\n3. If a sum doubles in n years at compound interest, it becomes 8 times in 4n years.\n4. The compound interest for the third year alone is P(1 + r/100)³ × r/100.","options":["Only two","Only three","Only one","All four"],"answer":0,"explanation":"1 and 2 are true. 3 is false: doubling every n years gives 2⁴ = 16 times in 4n years (8 times takes 3n). 4 is false: the third year's interest is P(1 + r/100)² × r/100.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. समान सांकेतिक दर पर, अर्द्धवार्षिक संयोजन से एक वर्ष में वार्षिक संयोजन की तुलना में अधिक ब्याज मिलता है।\n2. 2 वर्ष के लिए CI और SI का अंतर P(r/100)² होता है।\n3. यदि चक्रवृद्धि ब्याज पर कोई धनराशि n वर्ष में दुगुनी हो जाती है, तो वह 4n वर्ष में 8 गुनी हो जाती है।\n4. केवल तीसरे वर्ष का चक्रवृद्धि ब्याज P(1 + r/100)³ × r/100 होता है।","optionsHi":["केवल दो","केवल तीन","केवल एक","सभी चारों"],"explanationHi":"1 और 2 सही हैं। 3 गलत है: हर n वर्ष में दुगुना होने पर 4n वर्ष में 2⁴ = 16 गुना होता है (8 गुना होने में 3n वर्ष लगते हैं)। 4 गलत है: तीसरे वर्ष का ब्याज P(1 + r/100)² × r/100 होता है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-54","question":"A loan of ₹9,000 at 20% per annum compound interest is repaid in two annual instalments, the second being twice the first. What is the first instalment?","options":["₹3,000","₹3,600","₹4,500","₹4,050"],"answer":3,"explanation":"x/1.2 + 2x/1.44 = 9,000 gives x(5/6 + 25/18) = (40/18)x = 9,000, so x = ₹4,050. Check: 4,050/1.2 = 3,375 and 8,100/1.44 = 5,625, total ₹9,000.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"20% वार्षिक चक्रवृद्धि ब्याज की दर पर ₹9,000 का ऋण दो वार्षिक किस्तों में चुकाया जाता है, जिनमें दूसरी किस्त पहली से दुगुनी है। पहली किस्त कितनी है?","optionsHi":["₹3,000","₹3,600","₹4,500","₹4,050"],"explanationHi":"x/1.2 + 2x/1.44 = 9,000 से x(5/6 + 25/18) = (40/18)x = 9,000, अतः x = ₹4,050। जाँच: 4,050/1.2 = 3,375 और 8,100/1.44 = 5,625, कुल ₹9,000।","subtopic":"annual-compounding"},
  {"id":"quant-ci-55","question":"A sum amounts to ₹17,640 in 2 years at compound interest (compounded annually), and the simple interest on it for the same 2 years at the same rate is ₹1,600. What is the rate of interest?","options":["6%","5%","10%","4%"],"answer":1,"explanation":"SI per year = ₹800, so P = 800/r. Then (800/r)(1 + r)² = 17,640, i.e. r² − 20.05r + 1 = 0, giving r = 0.05 (the other root, 20, is absurd). Check: P = ₹16,000 and 16,000 × 1.05² = ₹17,640.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"चक्रवृद्धि ब्याज पर (वार्षिक संयोजित) कोई धनराशि 2 वर्ष में ₹17,640 हो जाती है, और उसी 2 वर्ष का उसी दर से साधारण ब्याज ₹1,600 है। ब्याज की दर कितनी है?","optionsHi":["6%","5%","10%","4%"],"explanationHi":"प्रतिवर्ष SI = ₹800, अतः P = 800/r। तब (800/r)(1 + r)² = 17,640, अर्थात् r² − 20.05r + 1 = 0, जिससे r = 0.05 (दूसरा मूल 20 असंभव है)। जाँच: P = ₹16,000 और 16,000 × 1.05² = ₹17,640।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-56","question":"₹10,000 can be invested for 3 years either at 10% per annum compound interest or at 12% per annum simple interest. Which earns more, and by how much?","options":["Simple interest scheme, by ₹290","Compound interest scheme, by ₹290","Both earn the same","Simple interest scheme, by ₹310"],"answer":0,"explanation":"CI = 10,000 × (1.331 − 1) = ₹3,310; SI = 10,000 × 0.36 = ₹3,600. The SI scheme earns ₹290 more; a higher simple rate can beat a lower compound rate over a short period.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"₹10,000 को 3 वर्ष के लिए या तो 10% वार्षिक चक्रवृद्धि ब्याज पर या 12% वार्षिक साधारण ब्याज पर निवेश किया जा सकता है। कौन-सा अधिक कमाता है, और कितना अधिक?","optionsHi":["साधारण ब्याज वाली योजना, ₹290 अधिक","चक्रवृद्धि ब्याज वाली योजना, ₹290 अधिक","दोनों समान कमाती हैं","साधारण ब्याज वाली योजना, ₹310 अधिक"],"explanationHi":"CI = 10,000 × (1.331 − 1) = ₹3,310; SI = 10,000 × 0.36 = ₹3,600। SI वाली योजना ₹290 अधिक कमाती है; कम अवधि में ऊँची साधारण दर नीची चक्रवृद्धि दर से आगे निकल सकती है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-57","question":"A car bought for ₹8,00,000 depreciates by 15% a year, while ₹5,00,000 kept in a deposit grows at 10% per annum compound interest. After 2 years, how do their values compare?","options":["The car is worth ₹27,000 more","The deposit is worth ₹27,000 more","They are worth the same","The deposit is worth ₹55,000 more"],"answer":1,"explanation":"Car: 8,00,000 × 0.85² = ₹5,78,000. Deposit: 5,00,000 × 1.1² = ₹6,05,000. The deposit is ₹27,000 more.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"₹8,00,000 में खरीदी गई एक कार का मूल्य प्रतिवर्ष 15% घटता है, जबकि जमा में रखे ₹5,00,000 पर 10% वार्षिक चक्रवृद्धि ब्याज मिलता है। 2 वर्ष बाद उनके मूल्यों की तुलना कैसी होगी?","optionsHi":["कार का मूल्य ₹27,000 अधिक है","जमा राशि का मूल्य ₹27,000 अधिक है","दोनों का मूल्य समान है","जमा राशि का मूल्य ₹55,000 अधिक है"],"explanationHi":"कार: 8,00,000 × 0.85² = ₹5,78,000। जमा राशि: 5,00,000 × 1.1² = ₹6,05,000। जमा राशि ₹27,000 अधिक है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-58","question":"What is the least number of complete years in which a sum invested at 20% per annum compound interest becomes more than double itself?","options":["4","6","3","5"],"answer":0,"explanation":"1.2² = 1.44, 1.2³ = 1.728 (< 2), 1.2⁴ = 2.0736 (> 2), so 4 years. Using simple interest (5 years) is the trap.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"20% वार्षिक चक्रवृद्धि ब्याज पर निवेश की गई कोई धनराशि कम से कम कितने पूर्ण वर्षों में अपने से दुगुने से अधिक हो जाएगी?","optionsHi":["4","6","3","5"],"explanationHi":"1.2² = 1.44, 1.2³ = 1.728 (< 2), 1.2⁴ = 2.0736 (> 2), अतः 4 वर्ष। साधारण ब्याज (5 वर्ष) मान लेना जाल है।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-59","question":"On ₹1,60,000 at 20% per annum for 1 year, by how much does the compound interest compounded quarterly exceed that compounded half-yearly?","options":["₹881","₹1,681","₹800","₹961"],"answer":0,"explanation":"Quarterly: 1,60,000 × 1.05⁴ = ₹1,94,481. Half-yearly: 1,60,000 × 1.1² = ₹1,93,600. Difference = ₹881.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"₹1,60,000 पर 20% वार्षिक दर से 1 वर्ष में त्रैमासिक संयोजित चक्रवृद्धि ब्याज, अर्द्धवार्षिक संयोजित चक्रवृद्धि ब्याज से कितना अधिक होगा?","optionsHi":["₹881","₹1,681","₹800","₹961"],"explanationHi":"त्रैमासिक: 1,60,000 × 1.05⁴ = ₹1,94,481। अर्द्धवार्षिक: 1,60,000 × 1.1² = ₹1,93,600। अंतर = ₹881।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-60","question":"Assertion (A): A sum that doubles in 3 years at compound interest becomes 8 times itself in 9 years.\nReason (R): Under compound interest, the amounts at equal intervals of time form a geometric progression.","options":["A is true but R is false","Both A and R are true, and R is the correct explanation of A","A is false but R is true","Both A and R are true, but R is not the correct explanation of A"],"answer":1,"explanation":"Every 3 years the amount is multiplied by 2, so in 9 years it becomes 2³ = 8 times; this is exactly the GP property in R.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"अभिकथन (A): चक्रवृद्धि ब्याज पर जो धनराशि 3 वर्ष में दुगुनी हो जाती है, वह 9 वर्ष में अपनी 8 गुनी हो जाती है।\nकारण (R): चक्रवृद्धि ब्याज में समान समय-अंतरालों पर मिश्रधन एक गुणोत्तर श्रेढ़ी बनाते हैं।","optionsHi":["A सत्य है लेकिन R असत्य है","A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A असत्य है लेकिन R सत्य है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है"],"explanationHi":"हर 3 वर्ष में मिश्रधन 2 से गुणा होता है, इसलिए 9 वर्ष में वह 2³ = 8 गुना हो जाता है; यही R में बताया गया GP का गुण है।","subtopic":"times-the-sum"},
  {"id":"quant-ci-61","question":"Money earns 10% per annum compound interest. Which is better: ₹12,000 now or ₹14,500 after 2 years?","options":["₹12,000 now, by ₹20 at the end of 2 years","₹14,500 later, by ₹2,500","₹14,500 later, by ₹20","Both are equal"],"answer":0,"explanation":"₹12,000 invested now grows to 12,000 × 1.21 = ₹14,520 in 2 years, ₹20 more than ₹14,500. Comparing ₹14,500 with ₹12,000 directly ignores the interest.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"धन पर 10% वार्षिक चक्रवृद्धि ब्याज मिलता है। कौन-सा बेहतर है: अभी ₹12,000 या 2 वर्ष बाद ₹14,500?","optionsHi":["अभी ₹12,000, ₹20 अधिक (2 वर्ष के अंत में)","बाद में ₹14,500, ₹2,500 अधिक","बाद में ₹14,500, ₹20 अधिक","दोनों बराबर हैं"],"explanationHi":"अभी निवेश किए गए ₹12,000 2 वर्ष में 12,000 × 1.21 = ₹14,520 हो जाते हैं, जो ₹14,500 से ₹20 अधिक है। ₹14,500 की सीधे ₹12,000 से तुलना करने में ब्याज की अनदेखी हो जाती है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-62","question":"A sum at compound interest amounts to ₹14,400 in 2 years and ₹20,736 in 4 years. What is the sum?","options":["₹9,600","₹12,000","₹11,000","₹10,000"],"answer":3,"explanation":"Over 2 years the growth factor is 20,736/14,400 = 1.44, so the rate is 20% a year. P = 14,400/1.44 = ₹10,000 (equivalently P = 14,400²/20,736).","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 2 वर्ष में ₹14,400 और 4 वर्ष में ₹20,736 हो जाती है। धनराशि कितनी है?","optionsHi":["₹9,600","₹12,000","₹11,000","₹10,000"],"explanationHi":"2 वर्ष में वृद्धि गुणक 20,736/14,400 = 1.44 है, अतः दर 20% वार्षिक है। P = 14,400/1.44 = ₹10,000 (समतुल्य रूप से P = 14,400²/20,736)।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-63","question":"A man invests ₹10,000 at 10% per annum compound interest. At the end of the first year he adds ₹5,000, and from the start of the third year the rate becomes 20%. What is his amount at the end of 3 years?","options":["₹19,965","₹20,328","₹21,780","₹21,120"],"answer":3,"explanation":"End of year 1: 11,000 + 5,000 = ₹16,000. Year 2 at 10%: ₹17,600. Year 3 at 20%: ₹21,120.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक व्यक्ति ₹10,000 को 10% वार्षिक चक्रवृद्धि ब्याज पर निवेश करता है। पहले वर्ष के अंत में वह ₹5,000 और जमा करता है, और तीसरे वर्ष के आरंभ से दर 20% हो जाती है। 3 वर्ष के अंत में उसका मिश्रधन कितना होगा?","optionsHi":["₹19,965","₹20,328","₹21,780","₹21,120"],"explanationHi":"पहले वर्ष के अंत में: 11,000 + 5,000 = ₹16,000। 10% पर दूसरा वर्ष: ₹17,600। 20% पर तीसरा वर्ष: ₹21,120।","subtopic":"annual-compounding"},
  {"id":"quant-ci-64","question":"At 10% per annum, the difference between CI and SI on a sum for 3 years is ₹210 more than the difference for 2 years. What is the sum?","options":["₹21,000","₹6,774","₹10,000","₹7,000"],"answer":2,"explanation":"For 2 years the difference is P × 0.01; for 3 years it is P × 0.031. So 0.021P = 210 and P = ₹10,000.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"10% वार्षिक दर पर किसी धनराशि के 3 वर्ष के CI और SI का अंतर, 2 वर्ष के अंतर से ₹210 अधिक है। धनराशि कितनी है?","optionsHi":["₹21,000","₹6,774","₹10,000","₹7,000"],"explanationHi":"2 वर्ष के लिए अंतर P × 0.01 है; 3 वर्ष के लिए P × 0.031। अतः 0.021P = 210 और P = ₹10,000।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-65","question":"What is the compound interest on ₹15,000 at 12% per annum for 2 years, compounded annually?","options":["₹3,600","₹3,816","₹3,960","₹18,816"],"answer":1,"explanation":"1.12² = 1.2544, so CI = 15,000 × 0.2544 = ₹3,816. ₹3,600 is the simple interest.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"₹15,000 पर 12% वार्षिक दर से 2 वर्ष का, वार्षिक रूप से संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹3,600","₹3,816","₹3,960","₹18,816"],"explanationHi":"1.12² = 1.2544, अतः CI = 15,000 × 0.2544 = ₹3,816। ₹3,600 साधारण ब्याज है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-66","question":"What will ₹20,000 amount to in 2 years at 15% per annum compound interest?","options":["₹26,450","₹26,000","₹6,450","₹26,500"],"answer":0,"explanation":"20,000 × 1.15 = 23,000, then × 1.15 = ₹26,450. ₹26,000 is the simple-interest amount, and ₹6,450 is the interest alone, not the amount asked for.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"₹20,000 की धनराशि 15% वार्षिक चक्रवृद्धि ब्याज की दर से 2 वर्ष में कितनी हो जाएगी?","optionsHi":["₹26,450","₹26,000","₹6,450","₹26,500"],"explanationHi":"20,000 × 1.15 = 23,000, फिर × 1.15 = ₹26,450। ₹26,000 साधारण ब्याज वाला मिश्रधन है, और ₹6,450 केवल ब्याज है, पूछा गया मिश्रधन नहीं।","subtopic":"annual-compounding"},
  {"id":"quant-ci-67","question":"What will ₹50,000 amount to in 2 years at 6% per annum, compounded annually?","options":["₹56,000","₹56,360","₹6,180","₹56,180"],"answer":3,"explanation":"50,000 × 1.1236 = ₹56,180. Interest = 3,000 + 3,180 = ₹6,180.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"₹50,000 की धनराशि 6% वार्षिक दर से, वार्षिक रूप से संयोजित, 2 वर्ष में कितनी हो जाएगी?","optionsHi":["₹56,000","₹56,360","₹6,180","₹56,180"],"explanationHi":"50,000 × 1.1236 = ₹56,180। ब्याज = 3,000 + 3,180 = ₹6,180।","subtopic":"annual-compounding"},
  {"id":"quant-ci-68","question":"At what rate of compound interest per annum does ₹2,500 become ₹3,025 in 2 years?","options":["10.5%","11%","10%","21%"],"answer":2,"explanation":"3,025/2,500 = 1.21 = 1.1², so the rate is 10%. 21% is the total growth over 2 years.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"चक्रवृद्धि ब्याज की कितनी वार्षिक दर से ₹2,500 की धनराशि 2 वर्ष में ₹3,025 हो जाएगी?","optionsHi":["10.5%","11%","10%","21%"],"explanationHi":"3,025/2,500 = 1.21 = 1.1², अतः दर 10% है। 21% 2 वर्ष की कुल वृद्धि है।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-69","question":"A town of 40,000 people grows by 5% every year. What will its population be after 2 years?","options":["44,000","42,000","44,100","44,200"],"answer":2,"explanation":"Population grows like compound interest: 40,000 × 1.05² = 44,100. 44,000 adds 5% of 40,000 twice, forgetting that the second year's growth is on 42,000.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"40,000 लोगों के एक कस्बे की जनसंख्या प्रतिवर्ष 5% बढ़ती है। 2 वर्ष बाद उसकी जनसंख्या कितनी होगी?","optionsHi":["44,000","42,000","44,100","44,200"],"explanationHi":"जनसंख्या चक्रवृद्धि ब्याज की तरह बढ़ती है: 40,000 × 1.05² = 44,100। 44,000 में 40,000 का 5% दो बार जोड़ा गया है, यह भूलकर कि दूसरे वर्ष की वृद्धि 42,000 पर होती है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-70","question":"A scooter worth ₹80,000 loses 10% of its value every year. What will it be worth after 2 years?","options":["₹64,000","₹64,800","₹65,600","₹72,000"],"answer":1,"explanation":"80,000 × 0.9 × 0.9 = ₹64,800. Subtracting 20% in one go (₹64,000) ignores that the second fall is on a lower value.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"₹80,000 मूल्य के एक स्कूटर का मूल्य प्रतिवर्ष 10% घटता है। 2 वर्ष बाद उसका मूल्य कितना होगा?","optionsHi":["₹64,000","₹64,800","₹65,600","₹72,000"],"explanationHi":"80,000 × 0.9 × 0.9 = ₹64,800। एक साथ 20% घटाने (₹64,000) में यह अनदेखा हो जाता है कि दूसरी कमी घटे हुए मूल्य पर होती है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-71","question":"What is the compound interest on ₹40,000 at 10% per annum for 1 year, compounded half-yearly?","options":["₹4,100","₹4,000","₹4,200","₹4,050"],"answer":0,"explanation":"5% per half-year for 2 half-years: 1.05² = 1.1025, so CI = 40,000 × 0.1025 = ₹4,100.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"₹40,000 पर 10% वार्षिक दर से 1 वर्ष का, अर्द्धवार्षिक संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹4,100","₹4,000","₹4,200","₹4,050"],"explanationHi":"प्रति अर्द्धवर्ष 5%, 2 अर्द्धवर्षों के लिए: 1.05² = 1.1025, अतः CI = 40,000 × 0.1025 = ₹4,100।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-72","question":"What is the compound interest on ₹7,500 at 4% per annum for 2 years, compounded annually?","options":["₹600","₹624","₹606","₹612"],"answer":3,"explanation":"1.04² = 1.0816, so CI = 7,500 × 0.0816 = ₹612. ₹600 is the simple interest, missing the ₹12 interest on the first year's ₹300.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"₹7,500 पर 4% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज (वार्षिक संयोजन) कितना होगा?","optionsHi":["₹600","₹624","₹606","₹612"],"explanationHi":"1.04² = 1.0816, अतः CI = 7,500 × 0.0816 = ₹612। ₹600 साधारण ब्याज है, जिसमें पहले वर्ष के ₹300 पर मिलने वाले ₹12 ब्याज छूट जाते हैं।","subtopic":"annual-compounding"},
  {"id":"quant-ci-73","question":"What is the effective annual rate of interest for 8% per annum compounded quarterly (to two decimal places)?","options":["8.16%","8%","8.32%","8.24%"],"answer":3,"explanation":"2% per quarter for 4 quarters: 1.02⁴ = 1.08243, an effective rate of about 8.24%.","difficulty":"moderate","source":"IBPS PO · SBI PO","questionHi":"8% वार्षिक दर पर त्रैमासिक संयोजित ब्याज की प्रभावी वार्षिक दर कितनी होगी (दशमलव के दो स्थानों तक)?","optionsHi":["8.16%","8%","8.32%","8.24%"],"explanationHi":"प्रति तिमाही 2%, 4 तिमाहियों के लिए: 1.02⁴ = 1.08243, अर्थात् प्रभावी दर लगभग 8.24%।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-74","question":"On the same sum at 10% per annum for 2 years, what is the ratio of compound interest (compounded annually) to simple interest?","options":["11 : 10","20 : 21","21 : 20","1 : 1"],"answer":2,"explanation":"Take ₹100: CI for 2 years at 10% = ₹21 and SI = ₹20, so CI : SI = 21 : 20. 20 : 21 inverts the ratio, and 11 : 10 compares one year's amount with the principal.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"उसी धनराशि पर 10% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज (वार्षिक संयोजित) और साधारण ब्याज का अनुपात कितना होगा?","optionsHi":["11 : 10","20 : 21","21 : 20","1 : 1"],"explanationHi":"₹100 लें: 10% पर 2 वर्ष का CI = ₹21 और SI = ₹20, अतः CI : SI = 21 : 20। 20 : 21 अनुपात को उलट देता है, और 11 : 10 एक वर्ष के मिश्रधन की मूलधन से तुलना है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-75","question":"A sum amounts to ₹19,965 in 3 years at 10% per annum compound interest. What is the sum?","options":["₹15,360","₹15,000","₹16,500","₹14,500"],"answer":1,"explanation":"1.1³ = 1.331, so the principal = 19,965 ÷ 1.331 = ₹15,000. ₹15,360 comes from deducting simple interest (30%) instead of discounting at compound interest.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"कोई धनराशि 10% वार्षिक चक्रवृद्धि ब्याज की दर से 3 वर्ष में ₹19,965 हो जाती है। धनराशि कितनी है?","optionsHi":["₹15,360","₹15,000","₹16,500","₹14,500"],"explanationHi":"1.1³ = 1.331, अतः मूलधन = 19,965 ÷ 1.331 = ₹15,000। ₹15,360 चक्रवृद्धि ब्याज से बट्टा लगाने के बजाय साधारण ब्याज (30%) घटाने से आता है।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-76","question":"₹12,500 is invested at 8% per annum compound interest. What is the interest earned in the second year alone?","options":["₹1,080","₹1,000","₹2,080","₹1,160"],"answer":0,"explanation":"First-year interest = ₹1,000, so the second year starts on ₹13,500. Second-year interest = 8% of 13,500 = ₹1,080.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"₹12,500 को 8% वार्षिक चक्रवृद्धि ब्याज पर निवेश किया जाता है। केवल दूसरे वर्ष में अर्जित ब्याज कितना होगा?","optionsHi":["₹1,080","₹1,000","₹2,080","₹1,160"],"explanationHi":"पहले वर्ष का ब्याज = ₹1,000, अतः दूसरा वर्ष ₹13,500 से शुरू होता है। दूसरे वर्ष का ब्याज = 13,500 का 8% = ₹1,080।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-77","question":"₹31,250 grows to ₹36,450 in 2 years at compound interest. What is the annual rate?","options":["8%","8.32%","16%","9%"],"answer":0,"explanation":"36,450/31,250 = 1.1664 = 1.08², so the rate is 8%. Dividing the gain evenly (8.32%) treats it as simple interest.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"चक्रवृद्धि ब्याज पर ₹31,250 की धनराशि 2 वर्ष में ₹36,450 हो जाती है। वार्षिक दर कितनी है?","optionsHi":["8%","8.32%","16%","9%"],"explanationHi":"36,450/31,250 = 1.1664 = 1.08², अतः दर 8% है। लाभ को बराबर बाँट देना (8.32%) इसे साधारण ब्याज मान लेना है।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-78","question":"What is the compound interest on ₹24,000 at 5% per annum for 3 years, compounded annually?","options":["₹3,600","₹3,780","₹3,690","₹3,783"],"answer":3,"explanation":"1.05³ = 1.157625, so CI = 24,000 × 0.157625 = ₹3,783. ₹3,600 is the simple interest, and ₹3,780 uses the shortcut 3Pr² but drops the small Pr³ term (₹3).","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"₹24,000 पर 5% वार्षिक दर से 3 वर्ष का, वार्षिक रूप से संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹3,600","₹3,780","₹3,690","₹3,783"],"explanationHi":"1.05³ = 1.157625, अतः CI = 24,000 × 0.157625 = ₹3,783। ₹3,600 साधारण ब्याज है, और ₹3,780 शॉर्टकट 3Pr² लगाता है पर छोटा-सा Pr³ पद (₹3) छोड़ देता है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-79","question":"What will ₹20,000 amount to in 6 months at 8% per annum, compounded quarterly?","options":["₹20,800","₹21,632","₹20,808","₹20,816"],"answer":2,"explanation":"2% per quarter for 2 quarters: 20,000 × 1.02² = 20,000 × 1.0404 = ₹20,808.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"₹20,000 की धनराशि 8% वार्षिक दर से, त्रैमासिक संयोजित, 6 महीने में कितनी हो जाएगी?","optionsHi":["₹20,800","₹21,632","₹20,808","₹20,816"],"explanationHi":"प्रति तिमाही 2%, 2 तिमाहियों के लिए: 20,000 × 1.02² = 20,000 × 1.0404 = ₹20,808।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-80","question":"What will ₹10,000 amount to in 1½ years at 20% per annum, compounded half-yearly?","options":["₹13,000","₹13,310","₹13,200","₹14,400"],"answer":1,"explanation":"10% per half-year for 3 half-years: 10,000 × 1.1³ = ₹13,310.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"₹10,000 की धनराशि 20% वार्षिक दर से, अर्द्धवार्षिक संयोजित, 1½ वर्ष में कितनी हो जाएगी?","optionsHi":["₹13,000","₹13,310","₹13,200","₹14,400"],"explanationHi":"प्रति अर्द्धवर्ष 10%, 3 अर्द्धवर्षों के लिए: 10,000 × 1.1³ = ₹13,310।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-81","question":"The compound interest on a sum is ₹500 for the first year and ₹1,025 for the first two years together. What is the rate per annum?","options":["2.5%","5%","10%","5.25%"],"answer":1,"explanation":"Second-year interest = 1,025 − 500 = ₹525. The extra ₹25 is interest on the first year's ₹500, so the rate = 25/500 = 5%.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर पहले वर्ष का चक्रवृद्धि ब्याज ₹500 है और पहले दो वर्षों का कुल चक्रवृद्धि ब्याज ₹1,025 है। वार्षिक दर कितनी है?","optionsHi":["2.5%","5%","10%","5.25%"],"explanationHi":"दूसरे वर्ष का ब्याज = 1,025 − 500 = ₹525। अतिरिक्त ₹25 पहले वर्ष के ₹500 पर ब्याज है, अतः दर = 25/500 = 5%।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-82","question":"What is the compound interest on ₹30,000 at 7% per annum for 2 years, compounded annually?","options":["₹4,347","₹4,200","₹4,410","₹4,247"],"answer":0,"explanation":"1.07² = 1.1449, so CI = 30,000 × 0.1449 = ₹4,347. ₹4,200 is the simple interest; the extra ₹147 is 7% of the first year's ₹2,100 interest.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"₹30,000 पर 7% वार्षिक दर से 2 वर्ष का, वार्षिक रूप से संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹4,347","₹4,200","₹4,410","₹4,247"],"explanationHi":"1.07² = 1.1449, अतः CI = 30,000 × 0.1449 = ₹4,347। ₹4,200 साधारण ब्याज है; अतिरिक्त ₹147 पहले वर्ष के ₹2,100 ब्याज का 7% है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-83","question":"What sum earns ₹1,236 as compound interest in 2 years at 6% per annum, compounded annually?","options":["₹10,300","₹9,800","₹12,000","₹10,000"],"answer":3,"explanation":"Two-year CI factor at 6% = 0.1236. Sum = 1,236 ÷ 0.1236 = ₹10,000.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"कितनी धनराशि पर 6% वार्षिक दर से, वार्षिक रूप से संयोजित, 2 वर्ष में ₹1,236 चक्रवृद्धि ब्याज मिलता है?","optionsHi":["₹10,300","₹9,800","₹12,000","₹10,000"],"explanationHi":"6% पर 2 वर्ष का CI गुणक = 0.1236। धनराशि = 1,236 ÷ 0.1236 = ₹10,000।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-84","question":"A motorbike bought for ₹1,00,000 loses 10% of its value every year. After how many complete years will its value first fall below ₹70,000?","options":["3","5","4","6"],"answer":2,"explanation":"Values: 90,000, 81,000, 72,900, 65,610. It first drops below ₹70,000 after 4 years, not 3 (30% ÷ 10%).","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"₹1,00,000 में खरीदी गई एक मोटरसाइकिल का मूल्य प्रतिवर्ष 10% घटता है। कितने पूर्ण वर्षों के बाद उसका मूल्य पहली बार ₹70,000 से नीचे आएगा?","optionsHi":["3","5","4","6"],"explanationHi":"मूल्य: 90,000, 81,000, 72,900, 65,610। यह पहली बार 4 वर्ष बाद ₹70,000 से नीचे आता है, 3 वर्ष बाद नहीं (30% ÷ 10%)।","subtopic":"population-depreciation"},
  {"id":"quant-ci-85","question":"Which deposit grows faster: 6% per annum compounded annually or 5.9% per annum compounded half-yearly?","options":["5.9% compounded half-yearly","Both grow equally","6% compounded annually","It depends on the amount"],"answer":2,"explanation":"5.9% half-yearly gives 1.0295² = 1.05987, an effective rate of about 5.99%, just below 6%. So the 6% annual deposit is slightly better.","difficulty":"moderate","source":"IBPS PO · SBI PO","questionHi":"कौन-सी जमा तेजी से बढ़ती है: 6% वार्षिक दर पर वार्षिक संयोजित या 5.9% वार्षिक दर पर अर्द्धवार्षिक संयोजित?","optionsHi":["5.9% अर्द्धवार्षिक संयोजित","दोनों समान रूप से बढ़ती हैं","6% वार्षिक संयोजित","यह राशि पर निर्भर करता है"],"explanationHi":"5.9% अर्द्धवार्षिक से 1.0295² = 1.05987 मिलता है, अर्थात् प्रभावी दर लगभग 5.99%, जो 6% से थोड़ी कम है। अतः 6% वार्षिक वाली जमा थोड़ी बेहतर है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-86","question":"A state's GDP rises from ₹4 lakh crore to ₹4.84 lakh crore in 2 years. What is its compound annual growth rate?","options":["10.5%","10%","21%","11%"],"answer":1,"explanation":"4.84/4 = 1.21 = 1.1², so the CAGR is 10%. 10.5% simply halves the 21% total rise.","difficulty":"moderate","source":"IBPS PO · RBI Assistant","questionHi":"किसी राज्य का GDP 2 वर्ष में ₹4 लाख करोड़ से बढ़कर ₹4.84 लाख करोड़ हो जाता है। उसकी चक्रवृद्धि वार्षिक वृद्धि दर कितनी है?","optionsHi":["10.5%","10%","21%","11%"],"explanationHi":"4.84/4 = 1.21 = 1.1², अतः CAGR 10% है। 10.5% में कुल वृद्धि 21% को सीधे आधा कर दिया गया है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-87","question":"A flat bought for ₹50 lakh appreciates by 8% every year. What is its approximate value after 3 years?","options":["₹62.99 lakh","₹62 lakh","₹63.5 lakh","₹62.5 lakh"],"answer":0,"explanation":"50 × 1.08³ = 50 × 1.259712 ≈ ₹62.99 lakh. Adding 24% (₹62 lakh) treats it as simple growth.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"₹50 लाख में खरीदे गए एक फ्लैट का मूल्य प्रतिवर्ष 8% बढ़ता है। 3 वर्ष बाद उसका लगभग मूल्य कितना होगा?","optionsHi":["₹62.99 लाख","₹62 लाख","₹63.5 लाख","₹62.5 लाख"],"explanationHi":"50 × 1.08³ = 50 × 1.259712 ≈ ₹62.99 लाख। 24% जोड़ने (₹62 लाख) पर इसे साधारण वृद्धि मान लिया जाता है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-88","question":"A sum doubles in 5 years at compound interest and amounts to ₹64,000 after 15 years. What is the sum?","options":["₹16,000","₹21,333","₹4,000","₹8,000"],"answer":3,"explanation":"15 years = 3 doubling periods, so the sum is multiplied by 2³ = 8. Sum = 64,000 ÷ 8 = ₹8,000.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 5 वर्ष में दुगुनी हो जाती है और 15 वर्ष बाद ₹64,000 हो जाती है। धनराशि कितनी है?","optionsHi":["₹16,000","₹21,333","₹4,000","₹8,000"],"explanationHi":"15 वर्ष = 3 दुगुनी होने की अवधियाँ, अतः धनराशि 2³ = 8 से गुणा होती है। धनराशि = 64,000 ÷ 8 = ₹8,000।","subtopic":"times-the-sum"},
  {"id":"quant-ci-89","question":"Ravi puts ₹50,000 in a deposit at 8% compound interest, and Sita puts ₹54,000 in a deposit at 8% simple interest. After 2 years, how much more does Sita have than Ravi?","options":["₹4,000","₹3,680","₹4,640","₹4,320"],"answer":3,"explanation":"Ravi: 50,000 × 1.1664 = ₹58,320. Sita: 54,000 × 1.16 = ₹62,640. Difference = ₹4,320.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"रवि ₹50,000 को 8% चक्रवृद्धि ब्याज वाली जमा में रखता है, और सीता ₹54,000 को 8% साधारण ब्याज वाली जमा में रखती है। 2 वर्ष बाद सीता के पास रवि से कितना अधिक होगा?","optionsHi":["₹4,000","₹3,680","₹4,640","₹4,320"],"explanationHi":"रवि: 50,000 × 1.1664 = ₹58,320। सीता: 54,000 × 1.16 = ₹62,640। अंतर = ₹4,320।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-90","question":"A sum becomes 1.21 times itself in one year at compound interest, compounded half-yearly. What is the annual rate?","options":["21%","10%","20%","10.5%"],"answer":2,"explanation":"1.21 = 1.1², so the half-yearly rate is 10% and the annual rate is 20%. 21% is the effective, not the nominal, rate.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"अर्द्धवार्षिक संयोजित चक्रवृद्धि ब्याज पर कोई धनराशि एक वर्ष में अपनी 1.21 गुनी हो जाती है। वार्षिक दर कितनी है?","optionsHi":["21%","10%","20%","10.5%"],"explanationHi":"1.21 = 1.1², अतः अर्द्धवार्षिक दर 10% है और वार्षिक दर 20%। 21% प्रभावी दर है, सांकेतिक नहीं।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-91","question":"A plot bought for ₹25 lakh gains 20% in value every year. What is it worth after 3 years?","options":["₹40 lakh","₹43.2 lakh","₹42 lakh","₹45 lakh"],"answer":1,"explanation":"25 × 1.2³ = 25 × 1.728 = ₹43.2 lakh. Simple growth of 60% gives only ₹40 lakh.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"₹25 लाख में खरीदे गए एक भूखंड का मूल्य प्रतिवर्ष 20% बढ़ता है। 3 वर्ष बाद उसका मूल्य कितना होगा?","optionsHi":["₹40 लाख","₹43.2 लाख","₹42 लाख","₹45 लाख"],"explanationHi":"25 × 1.2³ = 25 × 1.728 = ₹43.2 लाख। 60% की साधारण वृद्धि से केवल ₹40 लाख आता है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-92","question":"The compound interest on ₹12,000 for 2 years at r% per annum, compounded annually, is ₹2,520. What is r?","options":["10","10.5","21","11"],"answer":0,"explanation":"Amount = ₹14,520 and 14,520/12,000 = 1.21 = 1.1². So r = 10.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"₹12,000 पर r% वार्षिक दर से 2 वर्ष का, वार्षिक रूप से संयोजित, चक्रवृद्धि ब्याज ₹2,520 है। r कितना है?","optionsHi":["10","10.5","21","11"],"explanationHi":"मिश्रधन = ₹14,520 और 14,520/12,000 = 1.21 = 1.1²। अतः r = 10।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-93","question":"On ₹40,000 at 10% per annum for 2 years, by how much does the compound interest compounded half-yearly exceed the compound interest compounded annually?","options":["₹220.25","₹200","₹410","₹110.13"],"answer":0,"explanation":"Half-yearly: 1.05⁴ = 1.21550625; annually: 1.1² = 1.21. Difference = 40,000 × 0.00550625 = ₹220.25.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"₹40,000 पर 10% वार्षिक दर से 2 वर्ष में अर्द्धवार्षिक संयोजित चक्रवृद्धि ब्याज, वार्षिक संयोजित चक्रवृद्धि ब्याज से कितना अधिक होगा?","optionsHi":["₹220.25","₹200","₹410","₹110.13"],"explanationHi":"अर्द्धवार्षिक: 1.05⁴ = 1.21550625; वार्षिक: 1.1² = 1.21। अंतर = 40,000 × 0.00550625 = ₹220.25।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-94","question":"A person deposits ₹10,000 at the start of each year for 3 years in a scheme paying 10% compound interest. What is the balance at the end of the third year?","options":["₹33,100","₹36,000","₹34,410","₹36,410"],"answer":3,"explanation":"The deposits grow for 3, 2 and 1 years: 13,310 + 12,100 + 11,000 = ₹36,410.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"एक व्यक्ति 10% चक्रवृद्धि ब्याज देने वाली योजना में 3 वर्ष तक प्रत्येक वर्ष के आरंभ में ₹10,000 जमा करता है। तीसरे वर्ष के अंत में शेष राशि कितनी होगी?","optionsHi":["₹33,100","₹36,000","₹34,410","₹36,410"],"explanationHi":"जमा राशियाँ क्रमशः 3, 2 और 1 वर्ष बढ़ती हैं: 13,310 + 12,100 + 11,000 = ₹36,410।","subtopic":"annual-compounding"},
  {"id":"quant-ci-95","question":"A town of 40,000 grows by 5% a year, but 1,000 people move away at the end of each year. What will the population be after 2 years?","options":["42,100","41,000","42,050","44,100"],"answer":2,"explanation":"Year 1: 42,000 − 1,000 = 41,000. Year 2: 41,000 × 1.05 − 1,000 = 43,050 − 1,000 = 42,050.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"40,000 की जनसंख्या वाला एक कस्बा प्रतिवर्ष 5% बढ़ता है, परंतु प्रत्येक वर्ष के अंत में 1,000 लोग बाहर चले जाते हैं। 2 वर्ष बाद जनसंख्या कितनी होगी?","optionsHi":["42,100","41,000","42,050","44,100"],"explanationHi":"पहला वर्ष: 42,000 − 1,000 = 41,000। दूसरा वर्ष: 41,000 × 1.05 − 1,000 = 43,050 − 1,000 = 42,050।","subtopic":"population-depreciation"},
  {"id":"quant-ci-96","question":"At 10% per annum compound interest, the interest for the third year on a sum exceeds the interest for the second year by ₹132. What is the sum?","options":["₹13,200","₹12,000","₹11,000","₹10,000"],"answer":1,"explanation":"Second-year interest = 0.11P and third-year interest = 0.121P. The difference 0.011P = ₹132, so P = ₹12,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"10% वार्षिक चक्रवृद्धि ब्याज की दर पर किसी धनराशि के तीसरे वर्ष का ब्याज दूसरे वर्ष के ब्याज से ₹132 अधिक है। धनराशि कितनी है?","optionsHi":["₹13,200","₹12,000","₹11,000","₹10,000"],"explanationHi":"दूसरे वर्ष का ब्याज = 0.11P और तीसरे वर्ष का ब्याज = 0.121P। अंतर 0.011P = ₹132, अतः P = ₹12,000।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-97","question":"At what annual rate, compounded half-yearly, will ₹5,000 amount to ₹6,655 in 1½ years?","options":["10%","20%","22%","21%"],"answer":1,"explanation":"6,655/5,000 = 1.331 = 1.1³ over three half-years. So the half-yearly rate is 10% and the annual rate 20%.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"अर्द्धवार्षिक संयोजित किस वार्षिक दर पर ₹5,000 की धनराशि 1½ वर्ष में ₹6,655 हो जाएगी?","optionsHi":["10%","20%","22%","21%"],"explanationHi":"तीन अर्द्धवर्षों में 6,655/5,000 = 1.331 = 1.1³। अतः अर्द्धवार्षिक दर 10% और वार्षिक दर 20% है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-98","question":"Bank A offers 10% per annum compounded annually and Bank B offers 9.5% per annum compounded half-yearly. On ₹1,00,000 for 2 years, which bank pays more and by about how much?","options":["Bank B, by ₹602.87","Bank A, by ₹500","Bank A, by ₹602.87","Both pay the same"],"answer":2,"explanation":"Bank A: 1.1² = 1.21 → ₹1,21,000. Bank B: 1.0475⁴ ≈ 1.20397 → ₹1,20,397.13. Bank A pays about ₹602.87 more; half-yearly compounding does not make up for a 0.5% lower rate.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"बैंक A वार्षिक संयोजित 10% वार्षिक दर देता है और बैंक B अर्द्धवार्षिक संयोजित 9.5% वार्षिक दर देता है। ₹1,00,000 पर 2 वर्ष के लिए कौन-सा बैंक अधिक देता है और लगभग कितना अधिक?","optionsHi":["बैंक B, ₹602.87 अधिक","बैंक A, ₹500 अधिक","बैंक A, ₹602.87 अधिक","दोनों समान देते हैं"],"explanationHi":"बैंक A: 1.1² = 1.21 → ₹1,21,000। बैंक B: 1.0475⁴ ≈ 1.20397 → ₹1,20,397.13। बैंक A लगभग ₹602.87 अधिक देता है; अर्द्धवार्षिक संयोजन 0.5% कम दर की भरपाई नहीं कर पाता।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-99","question":"At what annual rate is the difference between compound interest and simple interest on a sum for 2 years exactly 1% of the sum?","options":["1%","10%","5%","20%"],"answer":1,"explanation":"For 2 years, CI − SI = P × (r/100)². Setting this equal to P/100 gives (r/100)² = 0.01, so r = 10%.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"किस वार्षिक दर पर किसी धनराशि के 2 वर्ष के चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर ठीक उस धनराशि का 1% होगा?","optionsHi":["1%","10%","5%","20%"],"explanationHi":"2 वर्ष के लिए CI − SI = P × (r/100)²। इसे P/100 के बराबर रखने पर (r/100)² = 0.01, अतः r = 10%।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-100","question":"A sum doubles in 3 years at compound interest. The annual rate is closest to:","options":["26%","33.33%","30%","23%"],"answer":0,"explanation":"(1 + r)³ = 2 gives 1 + r = ∛2 ≈ 1.26, so r ≈ 26%. 33.33% is the simple-interest rate that doubles money in 3 years.","difficulty":"hard","source":"SSC CGL · CDS","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 3 वर्ष में दुगुनी हो जाती है। वार्षिक दर लगभग कितनी है?","optionsHi":["26%","33.33%","30%","23%"],"explanationHi":"(1 + r)³ = 2 से 1 + r = ∛2 ≈ 1.26, अतः r ≈ 26%। 33.33% वह साधारण ब्याज दर है जिस पर धन 3 वर्ष में दुगुना होता है।","subtopic":"times-the-sum"},
  {"id":"quant-ci-101","question":"The simple interest on a sum for 3 years at 10% per annum is ₹4,500. What is the compound interest on half that sum for 2 years at 20% per annum, compounded annually?","options":["₹6,600","₹3,000","₹3,600","₹3,300"],"answer":3,"explanation":"The sum = 4,500/0.3 = ₹15,000, so half = ₹7,500. CI at 20% for 2 years = 44%: 7,500 × 0.44 = ₹3,300.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर 10% वार्षिक दर से 3 वर्ष का साधारण ब्याज ₹4,500 है। उस धनराशि के आधे पर 20% वार्षिक दर से 2 वर्ष का, वार्षिक रूप से संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹6,600","₹3,000","₹3,600","₹3,300"],"explanationHi":"धनराशि = 4,500/0.3 = ₹15,000, अतः आधी = ₹7,500। 20% पर 2 वर्ष का CI = 44%: 7,500 × 0.44 = ₹3,300।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-102","question":"A village's population grows by 4% a year at compound rate. In 2 years it increased by 2,040. What was the population at the start?","options":["25,500","26,010","24,000","25,000"],"answer":3,"explanation":"Two-year growth = 1.04² − 1 = 8.16%. Population = 2,040 ÷ 0.0816 = 25,000. Using 8% gives 25,500.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"एक गाँव की जनसंख्या चक्रवृद्धि दर से प्रतिवर्ष 4% बढ़ती है। 2 वर्ष में यह 2,040 बढ़ गई। आरंभ में जनसंख्या कितनी थी?","optionsHi":["25,500","26,010","24,000","25,000"],"explanationHi":"2 वर्ष की वृद्धि = 1.04² − 1 = 8.16%। जनसंख्या = 2,040 ÷ 0.0816 = 25,000। 8% लेने पर 25,500 आता है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-103","question":"What is the compound interest on ₹25,000 for 3 years if the rates for the three years are 4%, 5% and 6% respectively?","options":["₹3,750","₹3,900","₹3,938","₹3,983"],"answer":2,"explanation":"Amount = 25,000 × 1.04 × 1.05 × 1.06 = 25,000 × 1.15752 = ₹28,938. CI = ₹3,938.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"₹25,000 पर 3 वर्ष का चक्रवृद्धि ब्याज कितना होगा, यदि तीनों वर्षों की दरें क्रमशः 4%, 5% और 6% हैं?","optionsHi":["₹3,750","₹3,900","₹3,938","₹3,983"],"explanationHi":"मिश्रधन = 25,000 × 1.04 × 1.05 × 1.06 = 25,000 × 1.15752 = ₹28,938। CI = ₹3,938।","subtopic":"varying-rates"},
  {"id":"quant-ci-104","question":"At 10% per annum, the compound interest on a sum for 2 years exceeds the compound interest on it for 1 year by ₹2,200. What is the sum?","options":["₹22,000","₹20,000","₹11,000","₹10,000"],"answer":1,"explanation":"2-year CI = 21% and 1-year CI = 10%, so the difference is 11% of the sum = ₹2,200. Sum = ₹20,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"10% वार्षिक दर पर किसी धनराशि का 2 वर्ष का चक्रवृद्धि ब्याज उसके 1 वर्ष के चक्रवृद्धि ब्याज से ₹2,200 अधिक है। धनराशि कितनी है?","optionsHi":["₹22,000","₹20,000","₹11,000","₹10,000"],"explanationHi":"2 वर्ष का CI = 21% और 1 वर्ष का CI = 10%, अतः अंतर धनराशि का 11% = ₹2,200। धनराशि = ₹20,000।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-105","question":"On ₹20,000 at 10% per annum for 1 year, by how much does the compound interest compounded half-yearly exceed the simple interest?","options":["₹50","₹100","₹25","₹205"],"answer":0,"explanation":"Half-yearly: 20,000 × (1.05² − 1) = ₹2,050. SI = ₹2,000. The extra ₹50 is 5% interest on the first half-year's ₹1,000.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"₹20,000 पर 10% वार्षिक दर से 1 वर्ष में अर्द्धवार्षिक संयोजित चक्रवृद्धि ब्याज, साधारण ब्याज से कितना अधिक होगा?","optionsHi":["₹50","₹100","₹25","₹205"],"explanationHi":"अर्द्धवार्षिक: 20,000 × (1.05² − 1) = ₹2,050। SI = ₹2,000। अतिरिक्त ₹50 पहले अर्द्धवर्ष के ₹1,000 पर 5% ब्याज है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-106","question":"A bacterial culture grows by 50% every hour. Starting from 6,400 cells, after how many complete hours will it first exceed 30,000 cells?","options":["4","3","5","8"],"answer":0,"explanation":"6,400 → 9,600 → 14,400 → 21,600 → 32,400. It first exceeds 30,000 after 4 hours.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक जीवाणु संवर्धन में हर घंटे कोशिकाएँ 50% बढ़ती हैं। 6,400 कोशिकाओं से शुरू करके, कितने पूर्ण घंटों बाद यह पहली बार 30,000 कोशिकाओं से अधिक होगा?","optionsHi":["4","3","5","8"],"explanationHi":"6,400 → 9,600 → 14,400 → 21,600 → 32,400। यह पहली बार 4 घंटे बाद 30,000 से अधिक होता है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-107","question":"A man borrows ₹10,000 at 10% per annum simple interest and lends the whole amount at 10% per annum compound interest, compounded half-yearly. What does he gain in 2 years?","options":["₹100","₹210","₹55.06","₹155.06"],"answer":3,"explanation":"He earns 10,000 × (1.05⁴ − 1) = ₹2,155.06 and pays ₹2,000 simple interest. Gain = ₹155.06.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक व्यक्ति ₹10,000 को 10% वार्षिक साधारण ब्याज पर उधार लेता है और पूरी राशि को 10% वार्षिक चक्रवृद्धि ब्याज पर, अर्द्धवार्षिक संयोजित, उधार दे देता है। 2 वर्ष में उसे कितना लाभ होता है?","optionsHi":["₹100","₹210","₹55.06","₹155.06"],"explanationHi":"वह 10,000 × (1.05⁴ − 1) = ₹2,155.06 कमाता है और ₹2,000 साधारण ब्याज चुकाता है। लाभ = ₹155.06।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-108","question":"At compound interest a sum becomes 1.5 times itself in 4 years. What will it become in 12 years?","options":["4.5 times","3 times","3.375 times","2.25 times"],"answer":2,"explanation":"12 years = three 4-year periods, so the factor is 1.5³ = 3.375. Multiplying 1.5 by 3 treats the growth as simple.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 4 वर्ष में अपनी 1.5 गुनी हो जाती है। 12 वर्ष में वह कितने गुनी हो जाएगी?","optionsHi":["4.5 गुनी","3 गुनी","3.375 गुनी","2.25 गुनी"],"explanationHi":"12 वर्ष = तीन 4-वर्षीय अवधियाँ, अतः गुणक 1.5³ = 3.375। 1.5 को 3 से गुणा करना वृद्धि को साधारण मान लेना है।","subtopic":"times-the-sum"},
  {"id":"quant-ci-109","question":"A car bought for ₹6 lakh loses 20% of its value each year. The owner sells it after 2 years and invests the money at 10% per annum compound interest for 2 years. What is the final amount?","options":["₹4,80,000","₹4,64,640","₹4,35,600","₹4,60,800"],"answer":1,"explanation":"Sale value = 6,00,000 × 0.64 = ₹3,84,000. After 2 years at 10%: 3,84,000 × 1.21 = ₹4,64,640.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"₹6 लाख में खरीदी गई एक कार का मूल्य प्रतिवर्ष 20% घटता है। मालिक उसे 2 वर्ष बाद बेचकर प्राप्त धन को 2 वर्ष के लिए 10% वार्षिक चक्रवृद्धि ब्याज पर निवेश कर देता है। अंतिम राशि कितनी होगी?","optionsHi":["₹4,80,000","₹4,64,640","₹4,35,600","₹4,60,800"],"explanationHi":"विक्रय मूल्य = 6,00,000 × 0.64 = ₹3,84,000। 10% पर 2 वर्ष बाद: 3,84,000 × 1.21 = ₹4,64,640।","subtopic":"population-depreciation"},
  {"id":"quant-ci-110","question":"A mutual fund loses 20% in its first year and gains 25% in its second year. What is its compound annual growth rate over the two years?","options":["2.5%","0%","5%","−2.5%"],"answer":1,"explanation":"0.8 × 1.25 = 1, so the investment is back where it started: the CAGR is 0%. Averaging −20% and +25% (2.5%) is the trap.","difficulty":"hard","source":"IBPS PO · RBI Assistant","questionHi":"एक म्यूचुअल फंड पहले वर्ष में 20% खोता है और दूसरे वर्ष में 25% कमाता है। दोनों वर्षों में उसकी चक्रवृद्धि वार्षिक वृद्धि दर कितनी है?","optionsHi":["2.5%","0%","5%","−2.5%"],"explanationHi":"0.8 × 1.25 = 1, अतः निवेश वहीं लौट आता है जहाँ से शुरू हुआ था: CAGR 0% है। −20% और +25% का औसत (2.5%) लेना जाल है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-111","question":"A town's population rises by 10% in every odd-numbered year and falls by 10% in every even-numbered year. If it is 1,00,000 at the start of year 1, what is it at the end of year 4?","options":["98,010","1,00,000","99,000","96,060"],"answer":0,"explanation":"Each pair of years multiplies by 1.1 × 0.9 = 0.99. After 2 pairs: 1,00,000 × 0.99² = 98,010.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी कस्बे की जनसंख्या प्रत्येक विषम वर्ष में 10% बढ़ती है और प्रत्येक सम वर्ष में 10% घटती है। यदि वर्ष 1 के आरंभ में यह 1,00,000 है, तो वर्ष 4 के अंत में कितनी होगी?","optionsHi":["98,010","1,00,000","99,000","96,060"],"explanationHi":"प्रत्येक दो वर्षों का जोड़ा 1.1 × 0.9 = 0.99 से गुणा करता है। 2 जोड़ों के बाद: 1,00,000 × 0.99² = 98,010।","subtopic":"population-depreciation"},
  {"id":"quant-ci-112","question":"A machine depreciates at a fixed rate every year, and after 2 years its value is 64% of the original. If it was bought for ₹5 lakh, what will it be worth after 3 years?","options":["₹2,40,000","₹2,80,000","₹3,20,000","₹2,56,000"],"answer":3,"explanation":"0.64 = 0.8², so it keeps 80% each year (20% depreciation). After 3 years: 5,00,000 × 0.8³ = 5,00,000 × 0.512 = ₹2,56,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक मशीन का मूल्य प्रतिवर्ष एक निश्चित दर से घटता है, और 2 वर्ष बाद उसका मूल्य मूल मूल्य का 64% रह जाता है। यदि वह ₹5 लाख में खरीदी गई थी, तो 3 वर्ष बाद उसका मूल्य कितना होगा?","optionsHi":["₹2,40,000","₹2,80,000","₹3,20,000","₹2,56,000"],"explanationHi":"0.64 = 0.8², अतः वह प्रतिवर्ष 80% बनाए रखती है (20% ह्रास)। 3 वर्ष बाद: 5,00,000 × 0.8³ = 5,00,000 × 0.512 = ₹2,56,000।","subtopic":"population-depreciation"},
  {"id":"quant-ci-113","question":"₹1 lakh is invested at 10% compound interest for 2 years, and the whole amount is then invested at 12% simple interest for 3 years. What is the final amount?","options":["₹1,58,000","₹1,70,000","₹1,64,560","₹1,66,000"],"answer":2,"explanation":"After 2 years: ₹1,21,000. Simple interest at 12% for 3 years adds 36%: 1,21,000 × 1.36 = ₹1,64,560.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk","questionHi":"₹1 लाख को 2 वर्ष के लिए 10% चक्रवृद्धि ब्याज पर निवेश किया जाता है, और फिर पूरी राशि को 3 वर्ष के लिए 12% साधारण ब्याज पर निवेश किया जाता है। अंतिम राशि कितनी होगी?","optionsHi":["₹1,58,000","₹1,70,000","₹1,64,560","₹1,66,000"],"explanationHi":"2 वर्ष बाद: ₹1,21,000। 3 वर्ष के लिए 12% साधारण ब्याज 36% जोड़ता है: 1,21,000 × 1.36 = ₹1,64,560।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-114","question":"A man borrows ₹80,000 at 8% per annum compound interest. He repays ₹43,312 at the end of 2 years. How much must he pay at the end of the third year to clear the loan?","options":["₹50,000","₹53,312","₹54,000","₹55,600"],"answer":2,"explanation":"Due after 2 years = 80,000 × 1.1664 = ₹93,312. After paying 43,312, ₹50,000 remains, which grows to ₹54,000 in a year.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक व्यक्ति 8% वार्षिक चक्रवृद्धि ब्याज पर ₹80,000 उधार लेता है। वह 2 वर्ष के अंत में ₹43,312 चुकाता है। ऋण चुकता करने के लिए उसे तीसरे वर्ष के अंत में कितना देना होगा?","optionsHi":["₹50,000","₹53,312","₹54,000","₹55,600"],"explanationHi":"2 वर्ष बाद देय = 80,000 × 1.1664 = ₹93,312। ₹43,312 चुकाने के बाद ₹50,000 शेष रहते हैं, जो एक वर्ष में बढ़कर ₹54,000 हो जाते हैं।","subtopic":"annual-compounding"},
  {"id":"quant-ci-115","question":"What is the compound interest on ₹15,625 for 9 months at 16% per annum, compounded quarterly?","options":["₹1,875","₹1,951","₹2,000","₹1,976"],"answer":1,"explanation":"4% per quarter for 3 quarters: 15,625 × 1.04³ = 15,625 × 1.124864 = ₹17,576. CI = ₹1,951. ₹1,875 is the simple interest.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"₹15,625 पर 16% वार्षिक दर से 9 महीने का, त्रैमासिक संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹1,875","₹1,951","₹2,000","₹1,976"],"explanationHi":"प्रति तिमाही 4%, 3 तिमाहियों के लिए: 15,625 × 1.04³ = 15,625 × 1.124864 = ₹17,576। CI = ₹1,951। ₹1,875 साधारण ब्याज है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-116","question":"On ₹50,000 for 2 years, which earns more: 10% per annum compound interest (compounded annually) or 10.5% per annum simple interest?","options":["Both earn the same","Compound interest, by ₹250","Simple interest, by ₹250","Compound interest, by ₹500"],"answer":0,"explanation":"CI for 2 years at 10% = 21% of the sum; SI at 10.5% for 2 years = 21% too. Both earn ₹10,500.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"₹50,000 पर 2 वर्ष के लिए कौन अधिक कमाता है: 10% वार्षिक चक्रवृद्धि ब्याज (वार्षिक संयोजित) या 10.5% वार्षिक साधारण ब्याज?","optionsHi":["दोनों समान कमाते हैं","चक्रवृद्धि ब्याज, ₹250 अधिक","साधारण ब्याज, ₹250 अधिक","चक्रवृद्धि ब्याज, ₹500 अधिक"],"explanationHi":"10% पर 2 वर्ष का CI = धनराशि का 21%; 10.5% पर 2 वर्ष का SI भी 21% है। दोनों ₹10,500 कमाते हैं।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-117","question":"A sum amounts to ₹11,664 in 2 years at compound interest (compounded annually), and the simple interest on it for the same 2 years at the same rate is ₹1,600. What is the sum?","options":["₹9,600","₹10,800","₹8,000","₹10,000"],"answer":3,"explanation":"Yearly SI = ₹800 = Pr. Amount = P + 2Pr + Pr² = P + 1,600 + 800r = 11,664. Trying r = 8%: P = 10,000 and 10,000 + 64 = 10,064 ✓. Sum = ₹10,000.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"चक्रवृद्धि ब्याज पर (वार्षिक संयोजित) कोई धनराशि 2 वर्ष में ₹11,664 हो जाती है, और उसी 2 वर्ष का उसी दर से साधारण ब्याज ₹1,600 है। धनराशि कितनी है?","optionsHi":["₹9,600","₹10,800","₹8,000","₹10,000"],"explanationHi":"वार्षिक SI = ₹800 = Pr। मिश्रधन = P + 2Pr + Pr² = P + 1,600 + 800r = 11,664। r = 8% आज़माने पर: P = 10,000 और 10,000 + 64 = 10,064 ✓। धनराशि = ₹10,000।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-118","question":"At compound interest, the interest on a sum is ₹1,100 for the second year and ₹1,331 for the fourth year. What is the sum?","options":["₹11,000","₹12,100","₹10,000","₹9,091"],"answer":2,"explanation":"Interest grows by (1 + r)² from year 2 to year 4: 1,331/1,100 = 1.21, so r = 10%. Second-year interest = P × 0.1 × 1.1 = 0.11P = 1,100, giving P = ₹10,000.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"चक्रवृद्धि ब्याज पर किसी धनराशि का दूसरे वर्ष का ब्याज ₹1,100 और चौथे वर्ष का ब्याज ₹1,331 है। धनराशि कितनी है?","optionsHi":["₹11,000","₹12,100","₹10,000","₹9,091"],"explanationHi":"वर्ष 2 से वर्ष 4 तक ब्याज (1 + r)² गुना बढ़ता है: 1,331/1,100 = 1.21, अतः r = 10%। दूसरे वर्ष का ब्याज = P × 0.1 × 1.1 = 0.11P = 1,100, जिससे P = ₹10,000।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-119","question":"Money can earn 10% per annum compound interest. Which is worth more today: ₹10,000 now, or ₹6,050 after 1 year plus ₹6,050 after 2 years — and by how much in today's money?","options":["₹10,000 now, by ₹500","The two payments, by ₹500","The two payments, by ₹2,100","Both are worth the same"],"answer":1,"explanation":"Present value = 6,050/1.1 + 6,050/1.21 = 5,500 + 5,000 = ₹10,500, which beats ₹10,000 by ₹500.","difficulty":"very-hard","source":"IBPS PO · RBI Grade B","questionHi":"धन पर 10% वार्षिक चक्रवृद्धि ब्याज मिल सकता है। आज के मूल्य में कौन-सा अधिक मूल्यवान है: अभी ₹10,000, या 1 वर्ष बाद ₹6,050 और 2 वर्ष बाद ₹6,050 — और कितना अधिक?","optionsHi":["अभी ₹10,000, ₹500 अधिक","दोनों भुगतान, ₹500 अधिक","दोनों भुगतान, ₹2,100 अधिक","दोनों का मूल्य समान है"],"explanationHi":"वर्तमान मूल्य = 6,050/1.1 + 6,050/1.21 = 5,500 + 5,000 = ₹10,500, जो ₹10,000 से ₹500 अधिक है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-120","question":"The compound interest on a sum for 3 years at 10% per annum equals the simple interest on it for 3 years at r% per annum. What is r (to two decimal places)?","options":["10","11.03","10.5","10.33"],"answer":1,"explanation":"CI for 3 years at 10% is 33.1% of the sum (10 + 11 + 12.1), and SI for 3 years is 3r%, so r = 33.1/3 ≈ 11.03. 10 assumes equal rates, 10.33 forgets compounding in the third year (31%), and 10.5 uses the 2-year CI of 21%.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"किसी धनराशि पर 10% वार्षिक दर से 3 वर्ष का चक्रवृद्धि ब्याज, उस पर r% वार्षिक दर से 3 वर्ष के साधारण ब्याज के बराबर है। r कितना है (दशमलव के दो स्थानों तक)?","optionsHi":["10","11.03","10.5","10.33"],"explanationHi":"10% पर 3 वर्ष का CI धनराशि का 33.1% है (10 + 11 + 12.1), और 3 वर्ष का SI 3r% है, अतः r = 33.1/3 ≈ 11.03। 10 में सभी दरें समान मान ली गई हैं, 10.33 तीसरे वर्ष का संयोजन भूल जाता है (31%), और 10.5 में 2 वर्ष का CI 21% लिया गया है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-121","question":"₹50,000 is split into two parts: X at 10% compound interest for 2 years and Y at 12% simple interest for 2 years. The total interest is ₹11,250. What is Y?","options":["₹25,000","₹20,000","₹30,000","₹27,500"],"answer":0,"explanation":"Rates for 2 years: 21% on X and 24% on Y. If all were at 21%, interest = ₹10,500; the extra ₹750 is 3% of Y, so Y = ₹25,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"₹50,000 को दो भागों में बाँटा जाता है: X को 2 वर्ष के लिए 10% चक्रवृद्धि ब्याज पर और Y को 2 वर्ष के लिए 12% साधारण ब्याज पर लगाया जाता है। कुल ब्याज ₹11,250 है। Y कितना है?","optionsHi":["₹25,000","₹20,000","₹30,000","₹27,500"],"explanationHi":"2 वर्ष की दरें: X पर 21% और Y पर 24%। यदि सब कुछ 21% पर होता, तो ब्याज ₹10,500 होता; अतिरिक्त ₹750 Y का 3% है, अतः Y = ₹25,000।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-122","question":"For how long must a sum be lent at 10% simple interest to earn the same interest that it earns in 2 years at 10% compound interest, compounded annually?","options":["2 years","2.5 years","2.2 years","2.1 years"],"answer":3,"explanation":"CI for 2 years = 21% of the sum. At 10% simple interest, 21% takes 2.1 years.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि को 10% साधारण ब्याज पर कितने समय के लिए उधार देना होगा ताकि वह उतना ही ब्याज कमाए जितना 10% चक्रवृद्धि ब्याज पर, वार्षिक संयोजित, 2 वर्ष में कमाती है?","optionsHi":["2 वर्ष","2.5 वर्ष","2.2 वर्ष","2.1 वर्ष"],"explanationHi":"2 वर्ष का CI = धनराशि का 21%। 10% साधारण ब्याज पर 21% के लिए 2.1 वर्ष लगते हैं।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-123","question":"A deposit earns 8% per annum compound interest while prices rise by 5% every year. By roughly what percent does its real purchasing power grow in 2 years?","options":["6%","3%","5.8%","6.1%"],"answer":2,"explanation":"Real growth factor per year = 1.08/1.05 ≈ 1.02857. Over 2 years: 1.02857² ≈ 1.058, about 5.8%. Subtracting rates (3% a year → 6%) is only an approximation.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO Mains","questionHi":"एक जमा पर 8% वार्षिक चक्रवृद्धि ब्याज मिलता है, जबकि कीमतें प्रतिवर्ष 5% बढ़ती हैं। 2 वर्ष में उसकी वास्तविक क्रय शक्ति लगभग कितने प्रतिशत बढ़ती है?","optionsHi":["6%","3%","5.8%","6.1%"],"explanationHi":"प्रतिवर्ष वास्तविक वृद्धि गुणक = 1.08/1.05 ≈ 1.02857। 2 वर्ष में: 1.02857² ≈ 1.058, लगभग 5.8%। दरों को घटाना (3% प्रतिवर्ष → 6%) केवल एक सन्निकटन है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-124","question":"₹1 lakh is invested at 12% compound interest, but 30% tax is paid each year out of that year's interest, and only the rest is reinvested. What is the value after 2 years?","options":["₹1,17,808","₹1,25,440","₹1,17,505.60","₹1,16,800"],"answer":2,"explanation":"Post-tax rate = 12 × 0.7 = 8.4%. Value = 1,00,000 × 1.084² = ₹1,17,505.60. Taxing 30% of the total 2-year interest at the end (₹1,17,808) ignores that tax leaves the fund every year.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"₹1 लाख को 12% चक्रवृद्धि ब्याज पर निवेश किया जाता है, परंतु हर वर्ष उस वर्ष के ब्याज में से 30% कर चुकाया जाता है, और केवल शेष का पुनर्निवेश होता है। 2 वर्ष बाद मूल्य कितना होगा?","optionsHi":["₹1,17,808","₹1,25,440","₹1,17,505.60","₹1,16,800"],"explanationHi":"कर के बाद की दर = 12 × 0.7 = 8.4%। मूल्य = 1,00,000 × 1.084² = ₹1,17,505.60। अंत में 2 वर्ष के कुल ब्याज पर 30% कर लगाना (₹1,17,808) इस बात की अनदेखी करता है कि कर हर वर्ष कोष से निकलता है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-125","question":"A person deposits ₹X at the end of each year for 3 years in a scheme paying 10% compound interest, and has ₹33,100 just after the third deposit. What is X?","options":["₹11,000","₹10,000","₹9,000","₹10,030"],"answer":1,"explanation":"The deposits grow for 2, 1 and 0 years: X(1.21 + 1.1 + 1) = 3.31X = 33,100, so X = ₹10,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"एक व्यक्ति 10% चक्रवृद्धि ब्याज देने वाली योजना में 3 वर्ष तक प्रत्येक वर्ष के अंत में ₹X जमा करता है, और तीसरी जमा के ठीक बाद उसके पास ₹33,100 हैं। X कितना है?","optionsHi":["₹11,000","₹10,000","₹9,000","₹10,030"],"explanationHi":"जमा राशियाँ क्रमशः 2, 1 और 0 वर्ष बढ़ती हैं: X(1.21 + 1.1 + 1) = 3.31X = 33,100, अतः X = ₹10,000।","subtopic":"annual-compounding"},
  {"id":"quant-ci-126","question":"The compound interest on ₹A for 2 years at 10% per annum (compounded annually) equals the simple interest on ₹B for 3 years at 7% per annum. What is A : B?","options":["1 : 1","10 : 7","3 : 2","7 : 10"],"answer":0,"explanation":"CI rate for 2 years at 10% = 21%; SI for 3 years at 7% = 21%. So 0.21A = 0.21B and A : B = 1 : 1.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"₹A पर 10% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज (वार्षिक संयोजित), ₹B पर 7% वार्षिक दर से 3 वर्ष के साधारण ब्याज के बराबर है। A : B कितना है?","optionsHi":["1 : 1","10 : 7","3 : 2","7 : 10"],"explanationHi":"10% पर 2 वर्ष की CI दर = 21%; 7% पर 3 वर्ष का SI = 21%। अतः 0.21A = 0.21B और A : B = 1 : 1।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-127","question":"On a sum at 20% per annum for 2 years, compound interest compounded half-yearly exceeds compound interest compounded annually by ₹482. What is the sum?","options":["₹24,100","₹48,200","₹10,000","₹20,000"],"answer":3,"explanation":"Half-yearly: 1.1⁴ = 1.4641; annually: 1.2² = 1.44. Difference = 0.0241 of the sum = ₹482, so the sum = ₹20,000.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"किसी धनराशि पर 20% वार्षिक दर से 2 वर्ष में अर्द्धवार्षिक संयोजित चक्रवृद्धि ब्याज, वार्षिक संयोजित चक्रवृद्धि ब्याज से ₹482 अधिक है। धनराशि कितनी है?","optionsHi":["₹24,100","₹48,200","₹10,000","₹20,000"],"explanationHi":"अर्द्धवार्षिक: 1.1⁴ = 1.4641; वार्षिक: 1.2² = 1.44। अंतर = धनराशि का 0.0241 = ₹482, अतः धनराशि = ₹20,000।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-128","question":"A sum becomes 1.69 times itself in 2 years at compound interest. The simple interest on the same sum at the same rate for 5 years is ₹6,000. What is the sum?","options":["₹3,550","₹6,000","₹3,000","₹4,000"],"answer":3,"explanation":"1.69 = 1.3², so the rate is 30%. SI for 5 years = 150% of the sum = ₹6,000, so the sum = ₹4,000.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 2 वर्ष में अपनी 1.69 गुनी हो जाती है। उसी धनराशि पर उसी दर से 5 वर्ष का साधारण ब्याज ₹6,000 है। धनराशि कितनी है?","optionsHi":["₹3,550","₹6,000","₹3,000","₹4,000"],"explanationHi":"1.69 = 1.3², अतः दर 30% है। 5 वर्ष का SI = धनराशि का 150% = ₹6,000, अतः धनराशि = ₹4,000।","subtopic":"times-the-sum"},
  {"id":"quant-ci-129","question":"The compound interest on a sum for the first year is ₹800, and for the first three years together it is ₹2,648 (compounded annually). What is the sum?","options":["₹8,800","₹10,000","₹8,000","₹6,620"],"answer":2,"explanation":"CI(3 years)/CI(1 year) = 3 + 3r + r² = 2,648/800 = 3.31, which gives r = 0.1. Since Pr = 800, the sum = ₹8,000.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"किसी धनराशि पर पहले वर्ष का चक्रवृद्धि ब्याज ₹800 है, और पहले तीन वर्षों का कुल चक्रवृद्धि ब्याज (वार्षिक संयोजित) ₹2,648 है। धनराशि कितनी है?","optionsHi":["₹8,800","₹10,000","₹8,000","₹6,620"],"explanationHi":"CI(3 वर्ष)/CI(1 वर्ष) = 3 + 3r + r² = 2,648/800 = 3.31, जिससे r = 0.1। चूँकि Pr = 800, धनराशि = ₹8,000।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-130","question":"₹10,000 is invested at 10% compound interest and ₹11,000 at 10% simple interest on the same day. After how many complete years does the compound-interest amount first exceed the simple-interest amount?","options":["5","6","7","10"],"answer":1,"explanation":"Compare 10,000 × 1.1ⁿ with 11,000 + 1,100n: at n = 5, 16,105 < 16,500; at n = 6, 17,715.61 > 17,600. So 6 years.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"₹10,000 को 10% चक्रवृद्धि ब्याज पर और ₹11,000 को 10% साधारण ब्याज पर एक ही दिन निवेश किया जाता है। कितने पूर्ण वर्षों के बाद चक्रवृद्धि ब्याज वाला मिश्रधन पहली बार साधारण ब्याज वाले मिश्रधन से अधिक होगा?","optionsHi":["5","6","7","10"],"explanationHi":"10,000 × 1.1ⁿ की तुलना 11,000 + 1,100n से करें: n = 5 पर, 16,105 < 16,500; n = 6 पर, 17,715.61 > 17,600। अतः 6 वर्ष।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-131","question":"At compound interest (compounded annually), the interest for the second year is 8% more than the interest for the first year. What is the rate of interest?","options":["8%","4%","16%","10%"],"answer":0,"explanation":"Second-year interest = first-year interest × (1 + r), because it is earned on the first year's amount. So 1 + r = 1.08 and r = 8%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"चक्रवृद्धि ब्याज (वार्षिक संयोजित) में दूसरे वर्ष का ब्याज पहले वर्ष के ब्याज से 8% अधिक है। ब्याज की दर कितनी है?","optionsHi":["8%","4%","16%","10%"],"explanationHi":"दूसरे वर्ष का ब्याज = पहले वर्ष का ब्याज × (1 + r), क्योंकि वह पहले वर्ष के मिश्रधन पर मिलता है। अतः 1 + r = 1.08 और r = 8%।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-132","question":"A fund grows by 12% in year 1, grows by 25% in year 2 and falls by 20% in year 3. What is its approximate compound annual growth rate over the three years?","options":["3.85%","5.67%","4%","12%"],"answer":0,"explanation":"Overall factor = 1.12 × 1.25 × 0.8 = 1.12. CAGR = ∛1.12 − 1 ≈ 3.85%. The average of the three returns (5.67%) overstates it.","difficulty":"very-hard","source":"IBPS PO Mains · RBI Grade B","questionHi":"एक फंड वर्ष 1 में 12% बढ़ता है, वर्ष 2 में 25% बढ़ता है और वर्ष 3 में 20% घटता है। तीन वर्षों में उसकी लगभग चक्रवृद्धि वार्षिक वृद्धि दर कितनी है?","optionsHi":["3.85%","5.67%","4%","12%"],"explanationHi":"कुल गुणक = 1.12 × 1.25 × 0.8 = 1.12। CAGR = ∛1.12 − 1 ≈ 3.85%। तीनों प्रतिफलों का औसत (5.67%) इसे बढ़ाकर आँकता है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-133","question":"The compound interest on a sum for the first 2 years is ₹2,100, and for the first 3 years it is ₹3,310 (compounded annually). What is the rate of interest?","options":["11.5%","5%","12.1%","10%"],"answer":3,"explanation":"Third-year interest = 3,310 − 2,100 = ₹1,210, and it equals the 2-year amount × r. Trying 10%: the sum is 2,100/0.21 = ₹10,000, the 2-year amount ₹12,100, and 10% of it is ₹1,210 ✓.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर पहले 2 वर्षों का चक्रवृद्धि ब्याज ₹2,100 है, और पहले 3 वर्षों का ₹3,310 है (वार्षिक संयोजित)। ब्याज की दर कितनी है?","optionsHi":["11.5%","5%","12.1%","10%"],"explanationHi":"तीसरे वर्ष का ब्याज = 3,310 − 2,100 = ₹1,210, और यह 2 वर्ष के मिश्रधन × r के बराबर है। 10% आज़माने पर: धनराशि 2,100/0.21 = ₹10,000, 2 वर्ष का मिश्रधन ₹12,100, और उसका 10% ₹1,210 है ✓।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-134","question":"The compound interest on a sum for 2 years is ₹832 and the simple interest for the same period at the same rate is ₹800. What is the compound interest on the sum for 3 years?","options":["₹1,200","₹1,280","₹1,298.56","₹1,248"],"answer":2,"explanation":"CI − SI = ₹32 = interest on one year's interest (₹400), so r = 8%. Sum = 400/0.08 = ₹5,000. 3-year CI = 5,000 × (1.08³ − 1) = 5,000 × 0.259712 = ₹1,298.56.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO","questionHi":"किसी धनराशि पर 2 वर्ष का चक्रवृद्धि ब्याज ₹832 है और उसी अवधि का उसी दर से साधारण ब्याज ₹800 है। उस धनराशि पर 3 वर्ष का चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹1,200","₹1,280","₹1,298.56","₹1,248"],"explanationHi":"CI − SI = ₹32 = एक वर्ष के ब्याज (₹400) पर ब्याज, अतः r = 8%। धनराशि = 400/0.08 = ₹5,000। 3 वर्ष का CI = 5,000 × (1.08³ − 1) = 5,000 × 0.259712 = ₹1,298.56।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-135","question":"A sum earns compound interest at 10% in the first year and 20% in the second year. What single annual rate, compounded annually for 2 years, gives the same amount?","options":["15%","14.89%","15.5%","14.5%"],"answer":1,"explanation":"Factor = 1.1 × 1.2 = 1.32. Equivalent rate = √1.32 − 1 ≈ 14.89%, a little below the plain average of 15%.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"किसी धनराशि पर पहले वर्ष 10% और दूसरे वर्ष 20% की दर से चक्रवृद्धि ब्याज मिलता है। 2 वर्ष के लिए, वार्षिक रूप से संयोजित, कौन-सी एकल वार्षिक दर समान मिश्रधन देगी?","optionsHi":["15%","14.89%","15.5%","14.5%"],"explanationHi":"गुणक = 1.1 × 1.2 = 1.32। समतुल्य दर = √1.32 − 1 ≈ 14.89%, जो सामान्य औसत 15% से थोड़ी कम है।","subtopic":"varying-rates"},
  {"id":"quant-ci-136","question":"What is the compound interest on ₹64,000 for 1 year at 15% per annum, compounded half-yearly?","options":["₹9,960","₹9,600","₹10,080","₹9,840"],"answer":0,"explanation":"7.5% per half-year: 1.075² = 1.155625. CI = 64,000 × 0.155625 = ₹9,960.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"₹64,000 पर 15% वार्षिक दर से 1 वर्ष का, अर्द्धवार्षिक संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹9,960","₹9,600","₹10,080","₹9,840"],"explanationHi":"प्रति अर्द्धवर्ष 7.5%: 1.075² = 1.155625। CI = 64,000 × 0.155625 = ₹9,960।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-137","question":"The compound interest on a sum for 2 years at 20% per annum exceeds the compound interest on it for 2 years at 10% per annum by ₹2,300. What is the sum?","options":["₹11,500","₹23,000","₹12,000","₹10,000"],"answer":3,"explanation":"2-year CI rates: 44% at 20% and 21% at 10%. The 23% difference = ₹2,300, so the sum = ₹10,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर 20% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज, उसी पर 10% वार्षिक दर से 2 वर्ष के चक्रवृद्धि ब्याज से ₹2,300 अधिक है। धनराशि कितनी है?","optionsHi":["₹11,500","₹23,000","₹12,000","₹10,000"],"explanationHi":"2 वर्ष की CI दरें: 20% पर 44% और 10% पर 21%। 23% का अंतर = ₹2,300, अतः धनराशि = ₹10,000।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-138","question":"At 25% per annum compound interest, the interest for the third year on a sum is ₹3,125. What is the sum?","options":["₹12,500","₹10,000","₹8,000","₹6,400"],"answer":2,"explanation":"Third-year interest = P × 1.25² × 0.25 = 0.390625P = 3,125, so P = ₹8,000.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"25% वार्षिक चक्रवृद्धि ब्याज की दर पर किसी धनराशि के तीसरे वर्ष का ब्याज ₹3,125 है। धनराशि कितनी है?","optionsHi":["₹12,500","₹10,000","₹8,000","₹6,400"],"explanationHi":"तीसरे वर्ष का ब्याज = P × 1.25² × 0.25 = 0.390625P = 3,125, अतः P = ₹8,000।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-139","question":"In how many years will ₹1,331 amount to ₹1,771.561 at 10% per annum compound interest?","options":["4 years","3 years","2 years","5 years"],"answer":1,"explanation":"1,771.561/1,331 = 1.331 = 1.1³, so 3 years. Note that 1,331 is itself 11³, a distraction; only the ratio of amount to principal matters.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"10% वार्षिक चक्रवृद्धि ब्याज की दर पर ₹1,331 कितने वर्षों में ₹1,771.561 हो जाएगा?","optionsHi":["4 वर्ष","3 वर्ष","2 वर्ष","5 वर्ष"],"explanationHi":"1,771.561/1,331 = 1.331 = 1.1³, अतः 3 वर्ष। ध्यान दें कि 1,331 स्वयं 11³ है, जो भ्रम पैदा करता है; केवल मिश्रधन और मूलधन का अनुपात मायने रखता है।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-140","question":"What is the compound interest on ₹16,000 for 1½ years at 10% per annum, compounded half-yearly?","options":["₹2,522","₹2,400","₹2,480","₹2,555.31"],"answer":0,"explanation":"Half-yearly means 5% for 3 periods: 16,000 × 1.05³ = 18,522, so CI = ₹2,522. ₹2,480 compounds annually with a simple half-year at the end; ₹2,400 is simple interest.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹16,000 पर 10% वार्षिक दर से 1½ वर्ष का, अर्द्धवार्षिक संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹2,522","₹2,400","₹2,480","₹2,555.31"],"explanationHi":"अर्द्धवार्षिक का अर्थ है 3 अवधियों के लिए 5%: 16,000 × 1.05³ = 18,522, अतः CI = ₹2,522। ₹2,480 वार्षिक संयोजन करके अंत में आधे वर्ष का साधारण ब्याज जोड़ने से आता है; ₹2,400 साधारण ब्याज है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-141","question":"A sum lent at compound interest amounts to ₹13,310 in 3 years and to ₹14,641 in 4 years. What is the sum?","options":["₹12,100","₹9,317","₹10,000","₹11,000"],"answer":2,"explanation":"14,641/13,310 = 1.1, so the rate is 10% and P = 13,310/1.331 = ₹10,000. Treating the yearly interest of ₹1,331 as simple interest gives ₹9,317.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"चक्रवृद्धि ब्याज पर उधार दी गई कोई धनराशि 3 वर्ष में ₹13,310 और 4 वर्ष में ₹14,641 हो जाती है। धनराशि कितनी है?","optionsHi":["₹12,100","₹9,317","₹10,000","₹11,000"],"explanationHi":"14,641/13,310 = 1.1, अतः दर 10% है और P = 13,310/1.331 = ₹10,000। ₹1,331 के वार्षिक ब्याज को साधारण ब्याज मान लेने पर ₹9,317 आता है।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-142","question":"The difference between the compound interest and the simple interest on a sum for 3 years at 10% per annum is ₹930. What is the sum?","options":["₹93,000","₹31,000","₹46,500","₹30,000"],"answer":3,"explanation":"For 3 years the difference is P(0.331 − 0.3) = 0.031P = 930, so P = ₹30,000. Using the 2-year formula P(r/100)² gives ₹93,000.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी धनराशि पर 10% वार्षिक दर से 3 वर्ष के चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर ₹930 है। धनराशि कितनी है?","optionsHi":["₹93,000","₹31,000","₹46,500","₹30,000"],"explanationHi":"3 वर्ष के लिए अंतर P(0.331 − 0.3) = 0.031P = 930, अतः P = ₹30,000। 2 वर्ष का सूत्र P(r/100)² लगाने पर ₹93,000 आता है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-143","question":"A loan of ₹33,100 at 10% per annum compound interest is repaid in three equal annual instalments, the first one year after the loan. What is each instalment?","options":["₹11,033.33","₹14,685.37","₹14,343.33","₹13,310"],"answer":3,"explanation":"33,100 = x(1/1.1 + 1/1.21 + 1/1.331) = x × 3,310/1,331, so x = ₹13,310. Dividing the 3-year amount (₹44,056.10) by 3 ignores that early instalments stop interest.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"10% वार्षिक चक्रवृद्धि ब्याज की दर पर ₹33,100 का ऋण तीन समान वार्षिक किस्तों में चुकाया जाता है, पहली किस्त ऋण के एक वर्ष बाद। प्रत्येक किस्त कितनी है?","optionsHi":["₹11,033.33","₹14,685.37","₹14,343.33","₹13,310"],"explanationHi":"33,100 = x(1/1.1 + 1/1.21 + 1/1.331) = x × 3,310/1,331, अतः x = ₹13,310। 3 वर्ष के मिश्रधन (₹44,056.10) को 3 से भाग देना इस बात की अनदेखी करता है कि पहले दी गई किस्तों पर ब्याज रुक जाता है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-144","question":"A town's population rose 10% in the first year, fell 10% in the second and rose 20% in the third. It is now 47,520. What was it three years ago?","options":["39,600","38,586","40,000","43,200"],"answer":2,"explanation":"The factor is 1.1 × 0.9 × 1.2 = 1.188, so the population was 47,520/1.188 = 40,000. Adding the rates (+20%) gives 39,600, and taking 18.8% off the present figure gives 38,586.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी कस्बे की जनसंख्या पहले वर्ष में 10% बढ़ी, दूसरे वर्ष में 10% घटी और तीसरे वर्ष में 20% बढ़ी। यह अब 47,520 है। तीन वर्ष पहले यह कितनी थी?","optionsHi":["39,600","38,586","40,000","43,200"],"explanationHi":"गुणक = 1.1 × 0.9 × 1.2 = 1.188, अतः जनसंख्या 47,520/1.188 = 40,000 थी। दरों को जोड़ने (+20%) पर 39,600 आता है, और वर्तमान संख्या में से 18.8% घटाने पर 38,586।","subtopic":"population-depreciation"},
  {"id":"quant-ci-145","question":"₹16,820 is divided between A, aged 18, and B, aged 20, so that their shares, invested at 5% per annum compound interest, give equal amounts when each turns 22. What is A's share?","options":["₹8,820","₹8,000","₹8,410","₹8,044.35"],"answer":1,"explanation":"A's share grows for 4 years and B's for 2, so a × 1.05⁴ = b × 1.05² and a : b = 1 : 1.1025 = 400 : 441; A gets 16,820 × 400/841 = ₹8,000. ₹8,044.35 uses simple interest.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"₹16,820 को A (आयु 18 वर्ष) और B (आयु 20 वर्ष) में इस प्रकार बाँटा जाता है कि 5% वार्षिक चक्रवृद्धि ब्याज पर निवेश करने पर, प्रत्येक के 22 वर्ष का होने पर उनके हिस्से समान मिश्रधन दें। A का हिस्सा कितना है?","optionsHi":["₹8,820","₹8,000","₹8,410","₹8,044.35"],"explanationHi":"A का हिस्सा 4 वर्ष और B का 2 वर्ष बढ़ता है, अतः a × 1.05⁴ = b × 1.05² और a : b = 1 : 1.1025 = 400 : 441; A को 16,820 × 400/841 = ₹8,000 मिलते हैं। ₹8,044.35 साधारण ब्याज के प्रयोग से आता है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-146","question":"What is the effective annual rate of interest for a nominal rate of 12% per annum compounded quarterly?","options":["12.36%","12%","12.55%","12.68%"],"answer":2,"explanation":"(1.03)⁴ − 1 = 12.5509% ≈ 12.55%. 12.36% is half-yearly compounding and 12.68% is monthly compounding.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"12% वार्षिक सांकेतिक दर पर त्रैमासिक संयोजित ब्याज की प्रभावी वार्षिक दर कितनी होगी?","optionsHi":["12.36%","12%","12.55%","12.68%"],"explanationHi":"(1.03)⁴ − 1 = 12.5509% ≈ 12.55%। 12.36% अर्द्धवार्षिक संयोजन की दर है और 12.68% मासिक संयोजन की।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-147","question":"A sum becomes 4 times itself in 6 years at compound interest. In how many years will it become 32 times itself?","options":["62 years","30 years","15 years","48 years"],"answer":2,"explanation":"If the yearly growth factor is k, then k⁶ = 4, and 32 = 4^2.5 = k¹⁵, so it takes 15 years. Simple-interest thinking (3P in 6 years, so 31P in 62 years) gives 62.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 6 वर्ष में अपनी 4 गुनी हो जाती है। वह कितने वर्षों में अपनी 32 गुनी हो जाएगी?","optionsHi":["62 वर्ष","30 वर्ष","15 वर्ष","48 वर्ष"],"explanationHi":"यदि वार्षिक वृद्धि गुणक k है, तो k⁶ = 4, और 32 = 4^2.5 = k¹⁵, अतः 15 वर्ष लगेंगे। साधारण ब्याज की सोच (6 वर्ष में 3P, अतः 31P के लिए 62 वर्ष) से 62 आता है।","subtopic":"times-the-sum"},
  {"id":"quant-ci-148","question":"The simple interest on a sum for 2 years is ₹2,400 and the compound interest on it for 2 years at the same rate is ₹2,544. What is the rate of interest?","options":["6%","12%","24%","14.4%"],"answer":1,"explanation":"One year's simple interest is ₹1,200; the extra ₹144 is interest on that ₹1,200 for a year, so r = 144/1,200 = 12%. Dividing 144 by the full ₹2,400 gives 6%.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी धनराशि पर 2 वर्ष का साधारण ब्याज ₹2,400 है और उसी दर से 2 वर्ष का चक्रवृद्धि ब्याज ₹2,544 है। ब्याज की दर कितनी है?","optionsHi":["6%","12%","24%","14.4%"],"explanationHi":"एक वर्ष का साधारण ब्याज ₹1,200 है; अतिरिक्त ₹144 उस ₹1,200 पर एक वर्ष का ब्याज है, अतः r = 144/1,200 = 12%। 144 को पूरे ₹2,400 से भाग देने पर 6% आता है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-149","question":"A man borrows ₹20,000 at 10% per annum compound interest. He pays ₹8,000 at the end of the first year and ₹8,000 at the end of the second. How much must he pay at the end of the third year to clear the loan?","options":["₹10,620","₹7,400","₹10,000","₹8,140"],"answer":3,"explanation":"Balance: 22,000 − 8,000 = 14,000; then 15,400 − 8,000 = 7,400; then 7,400 × 1.1 = ₹8,140. Subtracting the payments from the 3-year amount (26,620 − 16,000) ignores interest the payments save.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यक्ति 10% वार्षिक चक्रवृद्धि ब्याज पर ₹20,000 उधार लेता है। वह पहले वर्ष के अंत में ₹8,000 और दूसरे वर्ष के अंत में ₹8,000 चुकाता है। ऋण चुकता करने के लिए उसे तीसरे वर्ष के अंत में कितना देना होगा?","optionsHi":["₹10,620","₹7,400","₹10,000","₹8,140"],"explanationHi":"शेष: 22,000 − 8,000 = 14,000; फिर 15,400 − 8,000 = 7,400; फिर 7,400 × 1.1 = ₹8,140। 3 वर्ष के मिश्रधन में से भुगतान घटाना (26,620 − 16,000) उस ब्याज की अनदेखी करता है जो भुगतानों से बच जाता है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-150","question":"What is the compound interest on ₹25,000 for 3 years if the rates for the three successive years are 5%, 8% and 10%?","options":["₹5,750","₹6,202.10","₹31,185","₹6,185"],"answer":3,"explanation":"Amount = 25,000 × 1.05 × 1.08 × 1.10 = 31,185, so CI = ₹6,185. ₹5,750 adds the rates as simple interest; compounding at their average (7.67%) gives a different figure; ₹31,185 is the amount.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹25,000 पर 3 वर्ष का चक्रवृद्धि ब्याज कितना होगा, यदि तीन क्रमागत वर्षों की दरें 5%, 8% और 10% हैं?","optionsHi":["₹5,750","₹6,202.10","₹31,185","₹6,185"],"explanationHi":"मिश्रधन = 25,000 × 1.05 × 1.08 × 1.10 = 31,185, अतः CI = ₹6,185। ₹5,750 दरों को साधारण ब्याज की तरह जोड़ने से आता है; उनके औसत (7.67%) पर संयोजन करने से भिन्न मान आता है; ₹31,185 मिश्रधन है।","subtopic":"varying-rates"},
  {"id":"quant-ci-151","question":"₹1,60,000 becomes ₹1,94,481 in 2 years when interest is compounded half-yearly. What is the rate of interest per annum?","options":["5%","10.25%","10.78%","10%"],"answer":3,"explanation":"194481/160000 = 1.21550625 = 1.05⁴, so the half-yearly rate is 5% and the annual rate 10%. Treating the 2 years as annual compounding gives 10.25%, the effective rate.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"जब ब्याज अर्द्धवार्षिक संयोजित होता है, तो ₹1,60,000 की धनराशि 2 वर्ष में ₹1,94,481 हो जाती है। ब्याज की वार्षिक दर कितनी है?","optionsHi":["5%","10.25%","10.78%","10%"],"explanationHi":"194481/160000 = 1.21550625 = 1.05⁴, अतः अर्द्धवार्षिक दर 5% और वार्षिक दर 10% है। 2 वर्ष को वार्षिक संयोजन मान लेने पर 10.25% आता है, जो प्रभावी दर है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-152","question":"A machine bought for ₹1,25,000 loses 20% of its value every year (on the value at the start of that year). What is it worth after 3 years?","options":["₹50,000","₹64,000","₹80,000","₹51,200"],"answer":1,"explanation":"1,25,000 × 0.8³ = ₹64,000. Taking 60% off at once (simple depreciation) gives ₹50,000; ₹80,000 is after 2 years.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹1,25,000 में खरीदी गई एक मशीन का मूल्य प्रतिवर्ष 20% घटता है (उस वर्ष के आरंभ के मूल्य पर)। 3 वर्ष बाद उसका मूल्य कितना होगा?","optionsHi":["₹50,000","₹64,000","₹80,000","₹51,200"],"explanationHi":"1,25,000 × 0.8³ = ₹64,000। एक साथ 60% घटाने (साधारण ह्रास) पर ₹50,000 आता है; ₹80,000 2 वर्ष बाद का मूल्य है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-153","question":"A sum at compound interest amounts to ₹8,820 in 2 years and ₹9,261 in 3 years. What is the compound interest for the first 2 years?","options":["₹820","₹441","₹800","₹1,261"],"answer":0,"explanation":"9,261/8,820 = 1.05, so the rate is 5% and P = 8,820/1.1025 = 8,000; CI for 2 years = ₹820. ₹441 is only the third year's interest and ₹800 is simple interest.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 2 वर्ष में ₹8,820 और 3 वर्ष में ₹9,261 हो जाती है। पहले 2 वर्षों का चक्रवृद्धि ब्याज कितना है?","optionsHi":["₹820","₹441","₹800","₹1,261"],"explanationHi":"9,261/8,820 = 1.05, अतः दर 5% है और P = 8,820/1.1025 = 8,000; 2 वर्ष का CI = ₹820। ₹441 केवल तीसरे वर्ष का ब्याज है और ₹800 साधारण ब्याज है।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-154","question":"The simple interest on a sum for 2 years is ₹1,600 and the compound interest for the same 2 years at the same rate is ₹1,680. What is the compound interest for 3 years?","options":["₹2,648","₹2,400","₹2,560","₹2,520"],"answer":0,"explanation":"Yearly SI is 800 and the extra 80 is 10% of 800, so r = 10% and P = 8,000; CI for 3 years = 8,000 × 0.331 = ₹2,648. Taking the third year's interest as 880 gives ₹2,560.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी धनराशि पर 2 वर्ष का साधारण ब्याज ₹1,600 है और उसी 2 वर्ष का उसी दर से चक्रवृद्धि ब्याज ₹1,680 है। 3 वर्ष का चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹2,648","₹2,400","₹2,560","₹2,520"],"explanationHi":"वार्षिक SI 800 है और अतिरिक्त 80, 800 का 10% है, अतः r = 10% और P = 8,000; 3 वर्ष का CI = 8,000 × 0.331 = ₹2,648। तीसरे वर्ष का ब्याज 880 मान लेने पर ₹2,560 आता है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-155","question":"A sum borrowed at 4% per annum compound interest is repaid in two equal annual instalments of ₹6,760 each. What was the sum borrowed?","options":["₹12,750","₹13,520","₹12,759.26","₹13,000"],"answer":0,"explanation":"Present value = 6,760/1.04 + 6,760/1.04² = 6,500 + 6,250 = ₹12,750. Discounting the second instalment at simple interest (÷1.08) gives ₹12,759.26.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"4% वार्षिक चक्रवृद्धि ब्याज पर उधार ली गई कोई धनराशि ₹6,760 की दो समान वार्षिक किस्तों में चुकाई जाती है। उधार ली गई धनराशि कितनी थी?","optionsHi":["₹12,750","₹13,520","₹12,759.26","₹13,000"],"explanationHi":"वर्तमान मूल्य = 6,760/1.04 + 6,760/1.04² = 6,500 + 6,250 = ₹12,750। दूसरी किस्त पर साधारण ब्याज से बट्टा लगाने (÷1.08) पर ₹12,759.26 आता है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-156","question":"On a sum lent at compound interest, the interest for the second year is ₹1,320 and for the third year ₹1,452. What is the sum?","options":["₹13,200","₹10,909.09","₹12,000","₹14,520"],"answer":2,"explanation":"1,452/1,320 = 1.1 so r = 10%. Second-year interest = P × 1.1 × 0.1 = 1,320, giving P = ₹12,000. Dividing 1,320 by 10% (₹13,200) forgets that the second year earns on P × 1.1.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"चक्रवृद्धि ब्याज पर उधार दी गई किसी धनराशि पर दूसरे वर्ष का ब्याज ₹1,320 और तीसरे वर्ष का ₹1,452 है। धनराशि कितनी है?","optionsHi":["₹13,200","₹10,909.09","₹12,000","₹14,520"],"explanationHi":"1,452/1,320 = 1.1, अतः r = 10%। दूसरे वर्ष का ब्याज = P × 1.1 × 0.1 = 1,320, जिससे P = ₹12,000। 1,320 को 10% से भाग देना (₹13,200) यह भूल जाता है कि दूसरे वर्ष में ब्याज P × 1.1 पर मिलता है।","subtopic":"year-wise-interest"},
  {"id":"quant-ci-157","question":"On ₹1,00,000 for 2 years, Scheme P pays 10% p.a. compounded half-yearly, Scheme Q pays 10.25% p.a. compounded annually and Scheme R pays 10.5% p.a. simple interest. Which ranking of the final amounts is correct?","options":["P highest, then Q, then R","R highest, then P and Q (equal)","P and Q equal, both above R","Q highest, then P, then R"],"answer":2,"explanation":"10% compounded half-yearly has an effective annual rate of 1.05² − 1 = 10.25%, so P and Q both give ₹1,21,550.63, while R gives ₹1,21,000.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"₹1,00,000 पर 2 वर्ष के लिए, योजना P 10% वार्षिक दर देती है, अर्द्धवार्षिक संयोजित; योजना Q 10.25% वार्षिक दर देती है, वार्षिक संयोजित; और योजना R 10.5% वार्षिक साधारण ब्याज देती है। अंतिम राशियों का कौन-सा क्रम सही है?","optionsHi":["P सबसे अधिक, फिर Q, फिर R","R सबसे अधिक, फिर P और Q (बराबर)","P और Q बराबर, दोनों R से अधिक","Q सबसे अधिक, फिर P, फिर R"],"explanationHi":"10% अर्द्धवार्षिक संयोजित की प्रभावी वार्षिक दर 1.05² − 1 = 10.25% है, अतः P और Q दोनों ₹1,21,550.63 देते हैं, जबकि R ₹1,21,000 देता है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-158","question":"What is the compound interest on ₹12,000 at 10% per annum for 2 years 3 months, if interest is compounded annually and simple interest is used for the part year?","options":["₹2,700","₹2,883","₹2,870.13","₹2,520"],"answer":1,"explanation":"12,000 × 1.21 × 1.025 = 14,883, so CI = ₹2,883. ₹2,520 stops at 2 years and ₹2,700 is simple interest.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹12,000 पर 10% वार्षिक दर से 2 वर्ष 3 माह का चक्रवृद्धि ब्याज कितना होगा, यदि ब्याज वार्षिक रूप से संयोजित हो और वर्ष के भाग के लिए साधारण ब्याज लिया जाए?","optionsHi":["₹2,700","₹2,883","₹2,870.13","₹2,520"],"explanationHi":"12,000 × 1.21 × 1.025 = 14,883, अतः CI = ₹2,883। ₹2,520 केवल 2 वर्ष तक का है और ₹2,700 साधारण ब्याज है।","subtopic":"annual-compounding"},
  {"id":"quant-ci-159","question":"The compound interest on a sum for 2 years at 8% per annum is ₹2,496. What is the simple interest on the same sum for 3 years at 6% per annum?","options":["₹2,808","₹2,700","₹3,744","₹2,865.24"],"answer":1,"explanation":"P = 2,496/0.1664 = 15,000, so SI = 15,000 × 18% = ₹2,700. Taking P = 2,496/0.16 (simple-interest thinking) gives ₹2,808; ₹2,865.24 is compound interest at 6%.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी धनराशि पर 8% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज ₹2,496 है। उसी धनराशि पर 6% वार्षिक दर से 3 वर्ष का साधारण ब्याज कितना होगा?","optionsHi":["₹2,808","₹2,700","₹3,744","₹2,865.24"],"explanationHi":"P = 2,496/0.1664 = 15,000, अतः SI = 15,000 × 18% = ₹2,700। P = 2,496/0.16 लेने (साधारण ब्याज की सोच) पर ₹2,808 आता है; ₹2,865.24 6% पर चक्रवृद्धि ब्याज है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-160","question":"What is the least number of complete years in which a sum lent at 20% per annum compound interest becomes more than double?","options":["5","4","3","6"],"answer":1,"explanation":"1.2³ = 1.728 and 1.2⁴ = 2.0736, so it first exceeds double after 4 years. At simple interest it would take 5 years, the trap answer.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"20% वार्षिक चक्रवृद्धि ब्याज पर उधार दी गई कोई धनराशि कम से कम कितने पूर्ण वर्षों में दुगुने से अधिक हो जाती है?","optionsHi":["5","4","3","6"],"explanationHi":"1.2³ = 1.728 और 1.2⁴ = 2.0736, अतः यह 4 वर्ष बाद पहली बार दुगुने से अधिक होती है। साधारण ब्याज पर इसमें 5 वर्ष लगते, जो जाल वाला उत्तर है।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-161","question":"What is the compound interest on ₹40,000 for 9 months at 16% per annum, compounded quarterly?","options":["₹4,800","₹4,928","₹4,994.56","₹6,794.34"],"answer":2,"explanation":"Quarterly rate 4% for 3 quarters: 40,000 × 1.04³ = 44,994.56, so CI = ₹4,994.56. Using 4 quarters gives ₹6,794.34; ₹4,800 is simple interest.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹40,000 पर 16% वार्षिक दर से 9 महीने का, त्रैमासिक संयोजित, चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹4,800","₹4,928","₹4,994.56","₹6,794.34"],"explanationHi":"त्रैमासिक दर 4%, 3 तिमाहियों के लिए: 40,000 × 1.04³ = 44,994.56, अतः CI = ₹4,994.56। 4 तिमाहियाँ लेने पर ₹6,794.34 आता है; ₹4,800 साधारण ब्याज है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-162","question":"A village of 20,000 grows by 5% a year through births, and at the end of every year (after the growth) 500 people move away. What is the population after 2 years?","options":["21,050","21,025","21,000","20,974"],"answer":1,"explanation":"Year 1: 21,000 − 500 = 20,500; year 2: 21,525 − 500 = 21,025. Subtracting 1,000 from 20,000 × 1.05² gives 21,050, which wrongly lets the first 500 keep growing.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"20,000 की जनसंख्या वाला एक गाँव जन्मों के कारण प्रतिवर्ष 5% बढ़ता है, और प्रत्येक वर्ष के अंत में (वृद्धि के बाद) 500 लोग बाहर चले जाते हैं। 2 वर्ष बाद जनसंख्या कितनी होगी?","optionsHi":["21,050","21,025","21,000","20,974"],"explanationHi":"वर्ष 1: 21,000 − 500 = 20,500; वर्ष 2: 21,525 − 500 = 21,025। 20,000 × 1.05² में से 1,000 घटाने पर 21,050 आता है, जो गलत ढंग से पहले 500 को भी बढ़ने देता है।","subtopic":"population-depreciation"},
  {"id":"quant-ci-163","question":"What is the difference between the compound interest on ₹50,000 for 1 year at 12% per annum compounded half-yearly and that compounded annually?","options":["₹720","₹360","₹90","₹180"],"answer":3,"explanation":"Half-yearly gives 50,000 × 1.06² = 56,180, annually 56,000, so the difference is ₹180 = P(r/2 ÷ 100)². Using P(r/100)² (the 2-year CI−SI formula) gives ₹720.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹50,000 पर 12% वार्षिक दर से 1 वर्ष का अर्द्धवार्षिक संयोजित चक्रवृद्धि ब्याज और वार्षिक संयोजित चक्रवृद्धि ब्याज का अंतर कितना है?","optionsHi":["₹720","₹360","₹90","₹180"],"explanationHi":"अर्द्धवार्षिक से 50,000 × 1.06² = 56,180, वार्षिक से 56,000, अतः अंतर ₹180 = P(r/2 ÷ 100)² है। P(r/100)² (2 वर्ष का CI−SI सूत्र) लगाने पर ₹720 आता है।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-164","question":"Half of ₹10,000 is lent at 10% per annum compound interest and the other half at x% per annum simple interest. The total interest after 2 years is ₹2,250. What is x?","options":["12%","12.5%","11.25%","24%"],"answer":0,"explanation":"The CI half earns 5,000 × 0.21 = 1,050, so the SI half earns 1,200 = 5,000 × 2x/100, giving x = 12. Taking the CI half as simple interest (1,000) gives 12.5%.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹10,000 का आधा भाग 10% वार्षिक चक्रवृद्धि ब्याज पर और शेष आधा x% वार्षिक साधारण ब्याज पर उधार दिया जाता है। 2 वर्ष बाद कुल ब्याज ₹2,250 है। x कितना है?","optionsHi":["12%","12.5%","11.25%","24%"],"explanationHi":"CI वाला आधा भाग 5,000 × 0.21 = 1,050 कमाता है, अतः SI वाला आधा भाग 1,200 = 5,000 × 2x/100 कमाता है, जिससे x = 12। CI वाले भाग को साधारण ब्याज (1,000) मान लेने पर 12.5% आता है।","subtopic":"ci-si-difference"},
  {"id":"quant-ci-165","question":"₹20,000 is invested for 3 years at 10% per annum. Interest is compounded annually in the first year and half-yearly after that. What is the compound interest?","options":["₹6,741.14","₹6,620","₹6,801.91","₹6,000"],"answer":0,"explanation":"Amount = 20,000 × 1.1 × 1.05⁴ = 26,741.14, so CI = ₹6,741.14. ₹6,620 is annual compounding throughout and ₹6,801.91 is half-yearly throughout.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹20,000 को 3 वर्ष के लिए 10% वार्षिक दर पर निवेश किया जाता है। ब्याज पहले वर्ष में वार्षिक रूप से और उसके बाद अर्द्धवार्षिक रूप से संयोजित होता है। चक्रवृद्धि ब्याज कितना होगा?","optionsHi":["₹6,741.14","₹6,620","₹6,801.91","₹6,000"],"explanationHi":"मिश्रधन = 20,000 × 1.1 × 1.05⁴ = 26,741.14, अतः CI = ₹6,741.14। ₹6,620 पूरे समय वार्षिक संयोजन से आता है और ₹6,801.91 पूरे समय अर्द्धवार्षिक संयोजन से।","subtopic":"half-yearly-quarterly"},
  {"id":"quant-ci-166","question":"In how many years will ₹6,250 amount to ₹7,290 at 8% per annum compound interest?","options":["2 years","2.08 years","3 years","1.5 years"],"answer":0,"explanation":"7,290/6,250 = 1.1664 = 1.08², so it takes 2 years. 2.08 years is what simple interest would need (1,040/500).","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"8% वार्षिक चक्रवृद्धि ब्याज की दर पर ₹6,250 कितने वर्षों में ₹7,290 हो जाएगा?","optionsHi":["2 वर्ष","2.08 वर्ष","3 वर्ष","1.5 वर्ष"],"explanationHi":"7,290/6,250 = 1.1664 = 1.08², अतः 2 वर्ष लगेंगे। 2.08 वर्ष वह है जो साधारण ब्याज के लिए चाहिए होता (1,040/500)।","subtopic":"rate-from-amounts"},
  {"id":"quant-ci-167","question":"At compound interest a sum doubles in 5 years. In 15 years, the interest earned will be how many times the principal?","options":["8 times","3 times","7 times","6 times"],"answer":2,"explanation":"15 years is three doubling periods, so the amount is 2³ = 8 times the principal and the interest is 8 − 1 = 7 times. Eight times is the amount, not the interest.","difficulty":"moderate","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 5 वर्ष में दोगुनी हो जाती है। 15 वर्ष में अर्जित ब्याज मूलधन का कितना गुना होगा?","optionsHi":["8 गुना","3 गुना","7 गुना","6 गुना"],"explanationHi":"15 वर्ष तीन दोगुना होने की अवधियाँ हैं, अतः मिश्रधन 2³ = 8 गुना और ब्याज 8 − 1 = 7 गुना है। आठ गुना मिश्रधन है, ब्याज नहीं।","subtopic":"times-the-sum","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-168","question":"At compound interest (compounded annually) the interest for two years together is 2.1 times the interest of the first year alone. What is the rate of interest per annum?","options":["10%","5%","20%","21%"],"answer":0,"explanation":"With rate r (as a fraction) the two-year interest is P(2r + r²) and the first-year interest is Pr, so the ratio is 2 + r = 2.1 and r = 0.1, i.e. 10%.","difficulty":"hard","questionHi":"चक्रवृद्धि ब्याज (वार्षिक संयोजन) पर दो वर्ष का कुल ब्याज केवल पहले वर्ष के ब्याज का 2.1 गुना है। वार्षिक ब्याज दर क्या है?","optionsHi":["10%","5%","20%","21%"],"explanationHi":"दर r (भिन्न के रूप में) होने पर दो वर्ष का ब्याज P(2r + r²) और पहले वर्ष का ब्याज Pr है, अतः अनुपात 2 + r = 2.1 और r = 0.1, अर्थात् 10%।","subtopic":"annual-compounding","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-169","question":"By how many percentage points (approximately) is the effective annual rate of 20% p.a. compounded quarterly higher than 20% p.a. compounded annually?","options":["1 point","1.25 points","2.1 points","1.55 points"],"answer":3,"explanation":"Quarterly compounding gives (1.05)⁴ = 1.21550625, an effective rate of about 21.55%, which is 1.55 points above 20%.","difficulty":"hard","questionHi":"20% वार्षिक दर, त्रैमासिक संयोजन की प्रभावी वार्षिक दर 20% वार्षिक दर, वार्षिक संयोजन से लगभग कितने प्रतिशत अंक अधिक है?","optionsHi":["1 अंक","1.25 अंक","2.1 अंक","1.55 अंक"],"explanationHi":"त्रैमासिक संयोजन से (1.05)⁴ = 1.21550625 मिलता है, अर्थात् प्रभावी दर लगभग 21.55%, जो 20% से 1.55 अंक अधिक है।","subtopic":"half-yearly-quarterly","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-170","question":"At compound interest (compounded annually) the interest for the third year is ₹1,452 and for the fifth year ₹1,756.92. What is the principal?","options":["₹10,000","₹12,000","₹14,520","₹13,200"],"answer":1,"explanation":"Yearly interest grows by (1 + r) each year, so (1 + r)² = 1756.92/1452 = 1.21 and r = 10%. Third-year interest = P × 1.21 × 0.1 = 1452 gives P = ₹12,000.","difficulty":"very-hard","questionHi":"चक्रवृद्धि ब्याज (वार्षिक संयोजन) पर तीसरे वर्ष का ब्याज ₹1,452 और पाँचवें वर्ष का ब्याज ₹1,756.92 है। मूलधन क्या है?","optionsHi":["₹10,000","₹12,000","₹14,520","₹13,200"],"explanationHi":"प्रतिवर्ष ब्याज (1 + r) गुना बढ़ता है, अतः (1 + r)² = 1756.92/1452 = 1.21 और r = 10%। तीसरे वर्ष का ब्याज = P × 1.21 × 0.1 = 1452 से P = ₹12,000।","subtopic":"year-wise-interest","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-171","question":"A sum becomes 1.65 times itself in 3 years when the rates of compound interest are 10%, 20% and r% for the first, second and third year respectively. What is r?","options":["20%","25%","22.5%","27.5%"],"answer":1,"explanation":"1.1 × 1.2 × (1 + r/100) = 1.65 gives 1 + r/100 = 1.25, so r = 25%. The simple average of rates would not apply to growth factors.","difficulty":"hard","questionHi":"एक धनराशि 3 वर्ष में अपनी 1.65 गुनी हो जाती है, जबकि चक्रवृद्धि ब्याज की दरें पहले, दूसरे और तीसरे वर्ष के लिए क्रमशः 10%, 20% और r% हैं। r का मान क्या है?","optionsHi":["20%","25%","22.5%","27.5%"],"explanationHi":"1.1 × 1.2 × (1 + r/100) = 1.65 से 1 + r/100 = 1.25, अतः r = 25%। दरों का साधारण औसत वृद्धि-गुणकों पर लागू नहीं होता।","subtopic":"varying-rates","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-172","question":"A town has 20,000 residents. In one year the number of men grows by 10% and the number of women by 5%, and the town now has 21,300 residents. How many men are there now?","options":["6,300","6,000","14,700","6,600"],"answer":3,"explanation":"Let men = M: 1.1M + 1.05(20,000 − M) = 21,300 gives 0.05M = 300, so M = 6,000 earlier and 6,000 × 1.1 = 6,600 now. 6,000 is the earlier count and 14,700 is the number of women now.","difficulty":"hard","questionHi":"एक कस्बे में 20,000 निवासी हैं। एक वर्ष में पुरुषों की संख्या 10% और महिलाओं की संख्या 5% बढ़ती है, और अब कस्बे में 21,300 निवासी हैं। अब पुरुषों की संख्या कितनी है?","optionsHi":["6,300","6,000","14,700","6,600"],"explanationHi":"पुरुष = M मानें: 1.1M + 1.05(20,000 − M) = 21,300 से 0.05M = 300, अतः पहले M = 6,000 और अब 6,000 × 1.1 = 6,600। 6,000 पहले की संख्या है और 14,700 अब महिलाओं की संख्या है।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-173","question":"A machine depreciates by 10% every year on its value at the start of the year. Its book value after 3 years is ₹14,580. What total depreciation was charged during the first 2 years?","options":["₹3,800","₹4,000","₹5,420","₹3,420"],"answer":0,"explanation":"Original cost = 14,580/0.9³ = ₹20,000 and the value after 2 years is 20,000 × 0.81 = ₹16,200, so depreciation was ₹3,800. ₹5,420 is the depreciation over all 3 years.","difficulty":"hard","questionHi":"एक मशीन का मूल्य प्रत्येक वर्ष के आरंभिक मूल्य पर 10% घटता है। 3 वर्ष बाद उसका बही मूल्य ₹14,580 है। पहले 2 वर्षों में कुल कितना अवमूल्यन हुआ?","optionsHi":["₹3,800","₹4,000","₹5,420","₹3,420"],"explanationHi":"मूल लागत = 14,580/0.9³ = ₹20,000 और 2 वर्ष बाद मूल्य 20,000 × 0.81 = ₹16,200, अतः अवमूल्यन ₹3,800 हुआ। ₹5,420 पूरे 3 वर्षों का अवमूल्यन है।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-174","question":"On a certain sum, the difference between compound interest and simple interest is ₹200 for 2 years and ₹620 for 3 years, at the same rate. What is the sum?","options":["₹25,000","₹15,000","₹20,000","₹10,000"],"answer":2,"explanation":"For 2 years the difference is Pr² and for 3 years Pr²(3 + r), so 620/200 = 3 + r gives r = 0.1. Then P × 0.01 = 200, so P = ₹20,000.","difficulty":"very-hard","questionHi":"किसी धनराशि पर एक ही दर से चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर 2 वर्ष के लिए ₹200 और 3 वर्ष के लिए ₹620 है। वह धनराशि क्या है?","optionsHi":["₹25,000","₹15,000","₹20,000","₹10,000"],"explanationHi":"2 वर्ष का अंतर Pr² और 3 वर्ष का Pr²(3 + r) होता है, अतः 620/200 = 3 + r से r = 0.1। तब P × 0.01 = 200, अतः P = ₹20,000।","subtopic":"ci-si-difference","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-175","question":"₹62,500 is invested for 2 years at 8% per annum, once with interest compounded half-yearly and once with interest compounded annually. By how much does the half-yearly amount exceed the annual amount?","options":["₹108.08","₹345.86","₹180.16","₹216.16"],"answer":3,"explanation":"Half-yearly: 62,500 × 1.04⁴ = ₹73,116.16. Annual: 62,500 × 1.08² = ₹72,900. The difference is ₹216.16.","difficulty":"very-hard","questionHi":"₹62,500 को 8% वार्षिक दर पर 2 वर्ष के लिए निवेश किया जाता है, एक बार अर्धवार्षिक संयोजन और एक बार वार्षिक संयोजन के साथ। अर्धवार्षिक मिश्रधन वार्षिक मिश्रधन से कितना अधिक है?","optionsHi":["₹108.08","₹345.86","₹180.16","₹216.16"],"explanationHi":"अर्धवार्षिक: 62,500 × 1.04⁴ = ₹73,116.16। वार्षिक: 62,500 × 1.08² = ₹72,900। अंतर ₹216.16 है।","subtopic":"half-yearly-quarterly","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-176","question":"At 15% per annum compound interest (compounded annually), what is the least number of complete years in which a sum more than doubles?","options":["4 years","5 years","6 years","7 years"],"answer":1,"explanation":"1.15⁴ = 1.749 is still below 2, while 1.15⁵ = 2.011 just exceeds it, so 5 years are needed. The rule of 72 would suggest about 4.8 years.","difficulty":"hard","questionHi":"15% वार्षिक चक्रवृद्धि ब्याज (वार्षिक संयोजन) पर कम से कम कितने पूरे वर्षों में कोई धनराशि दोगुने से अधिक हो जाती है?","optionsHi":["4 वर्ष","5 वर्ष","6 वर्ष","7 वर्ष"],"explanationHi":"1.15⁴ = 1.749 अभी 2 से कम है, जबकि 1.15⁵ = 2.011 उससे थोड़ा अधिक है, अतः 5 वर्ष लगते हैं। 72 का नियम लगभग 4.8 वर्ष बताता।","subtopic":"times-the-sum","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-177","question":"A person deposits ₹10,000 at the beginning of the first year and another ₹10,000 at the beginning of the second year in a scheme paying 20% per annum compound interest. What will he get at the end of the third year?","options":["₹29,280","₹28,800","₹31,680","₹34,560"],"answer":2,"explanation":"The first deposit grows for 3 years: 10,000 × 1.728 = 17,280. The second grows for 2 years: 10,000 × 1.44 = 14,400. Total ₹31,680.","difficulty":"hard","questionHi":"एक व्यक्ति 20% वार्षिक चक्रवृद्धि ब्याज देने वाली योजना में पहले वर्ष के आरंभ में ₹10,000 और दूसरे वर्ष के आरंभ में ₹10,000 जमा करता है। तीसरे वर्ष के अंत में उसे कितनी राशि मिलेगी?","optionsHi":["₹29,280","₹28,800","₹31,680","₹34,560"],"explanationHi":"पहली जमा राशि 3 वर्ष बढ़ती है: 10,000 × 1.728 = 17,280। दूसरी 2 वर्ष बढ़ती है: 10,000 × 1.44 = 14,400। कुल ₹31,680।","subtopic":"annual-compounding","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-178","question":"A man owes ₹14,520 payable after 2 years and ₹13,310 payable after 3 years. If money earns 10% per annum compound interest, what single payment today will clear both debts?","options":["₹22,000","₹27,830","₹24,200","₹21,000"],"answer":0,"explanation":"Discount each debt: 14,520/1.21 = 12,000 and 13,310/1.331 = 10,000, so ₹22,000 clears both. The undiscounted sum is ₹27,830.","difficulty":"very-hard","questionHi":"एक व्यक्ति पर ₹14,520, 2 वर्ष बाद देय, और ₹13,310, 3 वर्ष बाद देय, का ऋण है। यदि धन पर 10% वार्षिक चक्रवृद्धि ब्याज मिलता है, तो आज कितना एकमुश्त भुगतान दोनों ऋण चुका देगा?","optionsHi":["₹22,000","₹27,830","₹24,200","₹21,000"],"explanationHi":"प्रत्येक ऋण का वर्तमान मूल्य निकालें: 14,520/1.21 = 12,000 और 13,310/1.331 = 10,000, अतः ₹22,000 से दोनों ऋण चुक जाते हैं। बिना बट्टे का योग ₹27,830 है।","subtopic":"annual-compounding","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-179","question":"A man borrows ₹1,00,000 at 10% per annum compound interest and pays ₹60,500 at the end of the second year. How much must he pay at the end of the third year to clear the loan?","options":["₹66,550","₹60,500","₹64,550","₹71,550"],"answer":0,"explanation":"After 2 years the debt is 1,00,000 × 1.21 = 1,21,000. After paying 60,500, ₹60,500 remains and grows by 10% to ₹66,550.","difficulty":"hard","questionHi":"एक व्यक्ति 10% वार्षिक चक्रवृद्धि ब्याज पर ₹1,00,000 उधार लेता है और दूसरे वर्ष के अंत में ₹60,500 चुकाता है। ऋण चुकाने के लिए उसे तीसरे वर्ष के अंत में कितना चुकाना होगा?","optionsHi":["₹66,550","₹60,500","₹64,550","₹71,550"],"explanationHi":"2 वर्ष बाद ऋण 1,00,000 × 1.21 = 1,21,000 है। 60,500 चुकाने पर ₹60,500 बचते हैं, जो 10% बढ़कर ₹66,550 हो जाते हैं।","subtopic":"annual-compounding","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-180","question":"₹1,00,000 is invested for one year, first at 20% per annum compounded half-yearly and then (separately) at 21% per annum compounded annually. By how much do the interests differ?","options":["₹100","₹500","₹0","₹1,000"],"answer":2,"explanation":"Half-yearly at 20% gives 1.1² = 1.21, so ₹21,000 interest. The annual 21% also gives ₹21,000. They are identical, so the difference is zero.","difficulty":"very-hard","questionHi":"₹1,00,000 को एक वर्ष के लिए पहले 20% वार्षिक दर पर अर्धवार्षिक संयोजन के साथ और फिर (अलग से) 21% वार्षिक दर पर वार्षिक संयोजन के साथ निवेश किया जाता है। दोनों ब्याजों में कितना अंतर है?","optionsHi":["₹100","₹500","₹0","₹1,000"],"explanationHi":"20% पर अर्धवार्षिक संयोजन से 1.1² = 1.21 मिलता है, अर्थात् ब्याज ₹21,000। वार्षिक 21% से भी ₹21,000 मिलते हैं। दोनों समान हैं, अतः अंतर शून्य है।","subtopic":"half-yearly-quarterly","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-181","question":"Two sums in the ratio 2 : 3 are lent at 10% per annum compound interest for 2 years and 3 years respectively. What is the ratio of the compound interests earned?","options":["14 : 33","140 : 331","21 : 32","7 : 11"],"answer":1,"explanation":"Interest ratio = 2 × (1.21 − 1) : 3 × (1.331 − 1) = 0.42 : 0.993 = 420 : 993 = 140 : 331. Using 2 × 21 : 3 × 33 gives the near-miss 14 : 33.","difficulty":"very-hard","questionHi":"2 : 3 के अनुपात वाली दो धनराशियाँ 10% वार्षिक चक्रवृद्धि ब्याज पर क्रमशः 2 वर्ष और 3 वर्ष के लिए उधार दी जाती हैं। अर्जित चक्रवृद्धि ब्याजों का अनुपात क्या है?","optionsHi":["14 : 33","140 : 331","21 : 32","7 : 11"],"explanationHi":"ब्याजों का अनुपात = 2 × (1.21 − 1) : 3 × (1.331 − 1) = 0.42 : 0.993 = 420 : 993 = 140 : 331। 2 × 21 : 3 × 33 लेने पर लगभग-सही 14 : 33 मिलता है।","subtopic":"annual-compounding","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-182","question":"At compound interest (compounded annually) the interest for the third year is 21% more than the interest for the first year. What is the rate per annum?","options":["21%","20%","11%","10%"],"answer":3,"explanation":"Interest grows by the factor (1 + r) every year, so the third-year interest is (1 + r)² times the first-year interest, and (1 + r)² = 1.21 gives r = 10%.","difficulty":"moderate","questionHi":"चक्रवृद्धि ब्याज (वार्षिक संयोजन) पर तीसरे वर्ष का ब्याज पहले वर्ष के ब्याज से 21% अधिक है। वार्षिक दर क्या है?","optionsHi":["21%","20%","11%","10%"],"explanationHi":"ब्याज प्रतिवर्ष (1 + r) गुना बढ़ता है, इसलिए तीसरे वर्ष का ब्याज पहले वर्ष के ब्याज का (1 + r)² गुना है, और (1 + r)² = 1.21 से r = 10%।","subtopic":"year-wise-interest","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-183","question":"The compound interest on a sum for 2 years at x% per annum equals the simple interest on the same sum for 3 years at 7% per annum. What is x?","options":["10.5","21","10","7"],"answer":2,"explanation":"SI for 3 years at 7% is 21% of the sum, so (1 + x/100)² − 1 = 0.21, giving 1 + x/100 = 1.1 and x = 10.","difficulty":"hard","questionHi":"किसी धनराशि पर x% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज उसी धनराशि पर 7% वार्षिक दर से 3 वर्ष के साधारण ब्याज के बराबर है। x का मान क्या है?","optionsHi":["10.5","21","10","7"],"explanationHi":"7% पर 3 वर्ष का साधारण ब्याज मूलधन का 21% है, अतः (1 + x/100)² − 1 = 0.21, जिससे 1 + x/100 = 1.1 और x = 10।","subtopic":"ci-si-difference","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-184","question":"A sum amounts to ₹6,050 after 2 years and to ₹8,052.55 after 5 years at compound interest (compounded annually). What is the sum?","options":["₹5,000","₹5,500","₹5,250","₹4,800"],"answer":0,"explanation":"The 3 extra years multiply the amount by 8052.55/6050 = 1.331 = 1.1³, so r = 10%. Then P = 6050/1.21 = ₹5,000 (₹5,500 wrongly divides by 1.1 once).","difficulty":"very-hard","questionHi":"चक्रवृद्धि ब्याज (वार्षिक संयोजन) पर कोई धनराशि 2 वर्ष बाद ₹6,050 और 5 वर्ष बाद ₹8,052.55 हो जाती है। वह धनराशि क्या है?","optionsHi":["₹5,000","₹5,500","₹5,250","₹4,800"],"explanationHi":"अतिरिक्त 3 वर्षों में मिश्रधन 8052.55/6050 = 1.331 = 1.1³ गुना हो जाता है, अतः r = 10%। तब P = 6050/1.21 = ₹5,000 (₹5,500 में 1.1 से केवल एक बार भाग दिया गया है)।","subtopic":"rate-from-amounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-185","question":"A scooter depreciates by 12.5% every year on its value at the start of the year. After how many complete years will its value first fall below half of its original value?","options":["5 years","7 years","8 years","6 years"],"answer":3,"explanation":"Value factor 0.875⁵ = 0.513 is still above 0.5, while 0.875⁶ = 0.449 is below. Straight-line thinking (12.5% × 4 = 50%) would wrongly suggest 4 years.","difficulty":"hard","questionHi":"एक स्कूटर का मूल्य प्रत्येक वर्ष के आरंभिक मूल्य पर 12.5% घटता है। कितने पूरे वर्षों के बाद उसका मूल्य पहली बार अपने मूल मूल्य के आधे से कम होगा?","optionsHi":["5 वर्ष","7 वर्ष","8 वर्ष","6 वर्ष"],"explanationHi":"मूल्य गुणक 0.875⁵ = 0.513 अभी 0.5 से ऊपर है, जबकि 0.875⁶ = 0.449 उससे नीचे है। सरल रेखीय सोच (12.5% × 4 = 50%) से गलत रूप से 4 वर्ष लगते।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-186","question":"Consider: I. For a period of exactly one year with annual compounding, compound interest equals simple interest. II. For a period shorter than one year, the formula P(1 + r)^t always gives more than simple interest. III. If a sum doubles in n years at compound interest, it becomes 4 times in 2n years. IV. If the compound interest for 2 years is C, the compound interest for 4 years at the same rate is 2C. How many of these statements are correct?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is false because (1 + r)^t < 1 + rt when t < 1, and IV is false because growth is exponential: 4-year interest is more than double the 2-year interest.","difficulty":"hard","questionHi":"विचार कीजिए: I. ठीक एक वर्ष की अवधि के लिए, वार्षिक संयोजन के साथ, चक्रवृद्धि ब्याज साधारण ब्याज के बराबर होता है। II. एक वर्ष से कम अवधि के लिए सूत्र P(1 + r)^t सदैव साधारण ब्याज से अधिक मिश्रधन देता है। III. यदि कोई धनराशि चक्रवृद्धि ब्याज पर n वर्ष में दोगुनी होती है, तो वह 2n वर्ष में 4 गुनी हो जाती है। IV. यदि 2 वर्ष का चक्रवृद्धि ब्याज C है, तो उसी दर पर 4 वर्ष का चक्रवृद्धि ब्याज 2C होता है। इनमें से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। II गलत है क्योंकि t < 1 होने पर (1 + r)^t < 1 + rt होता है, और IV गलत है क्योंकि वृद्धि चरघातांकी है: 4 वर्ष का ब्याज 2 वर्ष के ब्याज के दोगुने से अधिक होता है।","subtopic":"annual-compounding","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-187","question":"Consider: I. The effective annual rate for 12% per annum compounded half-yearly is exactly 12%. II. Over 2 years, compound interest equals simple interest only if the rate is zero. III. If the rate is doubled, the difference between compound and simple interest for 2 years also doubles. IV. If the time is doubled from 2 to 4 years, the difference between compound and simple interest also exactly doubles. How many of these statements are correct?","options":["Only two","Only one","Only three","All four"],"answer":1,"explanation":"Only II is correct (the 2-year difference is Pr², zero only at r = 0). I is false (the effective rate is 12.36%), III is false (the difference becomes 4 times) and IV is false (it grows far more than 2 times).","difficulty":"very-hard","questionHi":"विचार कीजिए: I. 12% वार्षिक दर, अर्धवार्षिक संयोजन की प्रभावी वार्षिक दर ठीक 12% होती है। II. 2 वर्ष में चक्रवृद्धि ब्याज साधारण ब्याज के बराबर तभी होता है जब दर शून्य हो। III. यदि दर दोगुनी कर दी जाए तो 2 वर्ष के चक्रवृद्धि और साधारण ब्याज का अंतर भी दोगुना हो जाता है। IV. यदि समय 2 से बढ़ाकर 4 वर्ष कर दिया जाए तो चक्रवृद्धि और साधारण ब्याज का अंतर भी ठीक दोगुना हो जाता है। इनमें से कितने कथन सही हैं?","optionsHi":["केवल दो","केवल एक","केवल तीन","सभी चार"],"explanationHi":"केवल II सही है (2 वर्ष का अंतर Pr² है, जो केवल r = 0 पर शून्य होता है)। I गलत है (प्रभावी दर 12.36% है), III गलत है (अंतर 4 गुना हो जाता है) और IV गलत है (यह 2 गुने से कहीं अधिक बढ़ता है)।","subtopic":"ci-si-difference","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-188","question":"₹8,000 is invested at 20% per annum compounded half-yearly. How much interest is earned during the third half-year period alone?","options":["₹880","₹800","₹1,064.80","₹968"],"answer":3,"explanation":"The rate per half-year is 10%. Amount after two half-years is 8,000 × 1.21 = 9,680, and 10% of that is ₹968. ₹880 is the second half-year's interest.","difficulty":"hard","questionHi":"₹8,000 को 20% वार्षिक दर पर अर्धवार्षिक संयोजन के साथ निवेश किया जाता है। केवल तीसरी छमाही अवधि में कितना ब्याज अर्जित होता है?","optionsHi":["₹880","₹800","₹1,064.80","₹968"],"explanationHi":"प्रति छमाही दर 10% है। दो छमाही बाद मिश्रधन 8,000 × 1.21 = 9,680 है और उसका 10% ₹968 है। ₹880 दूसरी छमाही का ब्याज है।","subtopic":"year-wise-interest","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-189","question":"A sum invested for 1 year at 8% per annum compounded quarterly amounts to ₹54,121.61. What was the sum invested?","options":["₹50,000","₹50,039","₹50,113","₹51,000"],"answer":0,"explanation":"Quarterly rate is 2%, so the amount factor is 1.02⁴ = 1.08243216 and P = 54,121.61/1.08243216 = ₹50,000. Dividing by 1.08 (annual) gives ₹50,113.","difficulty":"hard","questionHi":"8% वार्षिक दर पर त्रैमासिक संयोजन के साथ 1 वर्ष के लिए निवेश की गई धनराशि ₹54,121.61 हो जाती है। निवेश की गई धनराशि क्या थी?","optionsHi":["₹50,000","₹50,039","₹50,113","₹51,000"],"explanationHi":"त्रैमासिक दर 2% है, अतः मिश्रधन गुणक 1.02⁴ = 1.08243216 और P = 54,121.61/1.08243216 = ₹50,000। 1.08 (वार्षिक) से भाग देने पर ₹50,113 आता है।","subtopic":"half-yearly-quarterly","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-190","question":"Which scheme gives the largest amount at the end of one year?","options":["8% p.a. compounded quarterly","8.2% p.a. compounded annually","8.1% p.a. compounded half-yearly","8.24% p.a. simple interest"],"answer":2,"explanation":"Effective annual rates are 8.243% (quarterly 8%), 8.264% (1.0405² − 1 for 8.1% half-yearly), 8.2% (annual) and 8.24% (simple). The half-yearly scheme is highest.","difficulty":"hard","questionHi":"एक वर्ष के अंत में कौन-सी योजना सबसे अधिक राशि देती है?","optionsHi":["8% वार्षिक, त्रैमासिक संयोजन","8.2% वार्षिक, वार्षिक संयोजन","8.1% वार्षिक, अर्धवार्षिक संयोजन","8.24% वार्षिक, साधारण ब्याज"],"explanationHi":"प्रभावी वार्षिक दरें हैं 8.243% (8% त्रैमासिक), 8.264% (8.1% अर्धवार्षिक के लिए 1.0405² − 1), 8.2% (वार्षिक) और 8.24% (साधारण)। अर्धवार्षिक योजना सबसे अधिक है।","subtopic":"half-yearly-quarterly","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-191","question":"At 5% per annum the difference between the compound interest and the simple interest on a sum for 3 years is ₹305. What is the sum?","options":["₹40,667","₹48,800","₹30,500","₹40,000"],"answer":3,"explanation":"The 3-year difference is P × r² × (3 + r) = P × 0.0025 × 3.05 = 0.007625P = 305, so P = ₹40,000. The shortcut P r² × 3 alone would give the near value ₹40,667.","difficulty":"hard","questionHi":"5% वार्षिक दर पर किसी धनराशि के 3 वर्ष के चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर ₹305 है। वह धनराशि क्या है?","optionsHi":["₹40,667","₹48,800","₹30,500","₹40,000"],"explanationHi":"3 वर्ष का अंतर P × r² × (3 + r) = P × 0.0025 × 3.05 = 0.007625P = 305, अतः P = ₹40,000। केवल P r² × 3 लेने पर लगभग ₹40,667 आता है।","subtopic":"ci-si-difference","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-192","question":"Town A has a population of 1,00,000 and grows 10% every year. Town B has 1,50,000 and shrinks 10% every year. After 2 years, by how many do their populations differ?","options":["0","500","1,000","2,000"],"answer":1,"explanation":"A = 1,00,000 × 1.21 = 1,21,000 and B = 1,50,000 × 0.81 = 1,21,500, so they differ by 500. Treating +10% and −10% as +20% and −20% would wrongly give equality.","difficulty":"very-hard","questionHi":"नगर A की जनसंख्या 1,00,000 है और वह प्रतिवर्ष 10% बढ़ती है। नगर B की जनसंख्या 1,50,000 है और वह प्रतिवर्ष 10% घटती है। 2 वर्ष बाद उनकी जनसंख्याओं में कितना अंतर है?","optionsHi":["0","500","1,000","2,000"],"explanationHi":"A = 1,00,000 × 1.21 = 1,21,000 और B = 1,50,000 × 0.81 = 1,21,500, अतः अंतर 500 है। +10% और −10% को +20% और −20% मान लेने पर गलत रूप से बराबरी आती।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-193","question":"A car loses 20% of its value every year (on the value at the start of that year). By what percentage of its original price will it have lost value after 3 years?","options":["51.2%","60%","48.8%","48%"],"answer":2,"explanation":"The remaining value is 0.8³ = 0.512, i.e. 51.2%, so the total loss is 100 − 51.2 = 48.8%. The 51.2% option is the value that remains.","difficulty":"moderate","questionHi":"एक कार का मूल्य प्रत्येक वर्ष (उस वर्ष के आरंभिक मूल्य पर) 20% घटता है। 3 वर्ष बाद मूल कीमत का कितना प्रतिशत मूल्य घट चुका होगा?","optionsHi":["51.2%","60%","48.8%","48%"],"explanationHi":"शेष मूल्य 0.8³ = 0.512, अर्थात् 51.2% है, अतः कुल हानि 100 − 51.2 = 48.8% है। 51.2% वाला विकल्प शेष मूल्य है।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-194","question":"At compound interest a sum trebles in 5 years. In how many years will the interest earned be 26 times the principal?","options":["15 years","25 years","13 years","10 years"],"answer":0,"explanation":"Interest of 26 times the sum means the amount is 27 times, and 27 = 3³, so three trebling periods are needed: 3 × 5 = 15 years.","difficulty":"very-hard","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 5 वर्ष में तिगुनी हो जाती है। कितने वर्षों में अर्जित ब्याज मूलधन का 26 गुना होगा?","optionsHi":["15 वर्ष","25 वर्ष","13 वर्ष","10 वर्ष"],"explanationHi":"ब्याज मूलधन का 26 गुना होने का अर्थ है कि मिश्रधन 27 गुना है, और 27 = 3³, अतः तिगुना होने की तीन अवधियाँ चाहिए: 3 × 5 = 15 वर्ष।","subtopic":"times-the-sum","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-195","question":"A sum becomes 9 times itself in 2 years at compound interest. By what factor will it grow in 5 years?","options":["243 times","45 times","81 times","729 times"],"answer":0,"explanation":"(1 + r)² = 9 gives 1 + r = 3, so after 5 years the factor is 3⁵ = 243. Multiplying 9 by 5 is not valid for compound growth.","difficulty":"moderate","questionHi":"चक्रवृद्धि ब्याज पर कोई धनराशि 2 वर्ष में अपनी 9 गुनी हो जाती है। 5 वर्ष में वह कितने गुनी हो जाएगी?","optionsHi":["243 गुना","45 गुना","81 गुना","729 गुना"],"explanationHi":"(1 + r)² = 9 से 1 + r = 3, अतः 5 वर्ष में गुणक 3⁵ = 243 है। चक्रवृद्धि वृद्धि में 9 को 5 से गुणा करना सही नहीं है।","subtopic":"times-the-sum","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-196","question":"A sum amounts to ₹28,800 at the end of the 2nd year and to ₹41,472 at the end of the 4th year at compound interest (compounded annually). What is the sum?","options":["₹24,000","₹22,000","₹20,000","₹18,000"],"answer":2,"explanation":"41,472/28,800 = 1.44 = (1 + r)², so r = 20%. Then P = 28,800/1.44 = ₹20,000; ₹24,000 would divide by 1.2 only once.","difficulty":"very-hard","questionHi":"चक्रवृद्धि ब्याज (वार्षिक संयोजन) पर कोई धनराशि दूसरे वर्ष के अंत में ₹28,800 और चौथे वर्ष के अंत में ₹41,472 हो जाती है। वह धनराशि क्या है?","optionsHi":["₹24,000","₹22,000","₹20,000","₹18,000"],"explanationHi":"41,472/28,800 = 1.44 = (1 + r)², अतः r = 20%। तब P = 28,800/1.44 = ₹20,000; ₹24,000 में केवल एक बार 1.2 से भाग दिया गया है।","subtopic":"rate-from-amounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-197","question":"At 10% per annum compound interest, the interest for the fourth year exceeds the interest for the third year by ₹484. What is the principal?","options":["₹44,000","₹40,000","₹48,400","₹36,000"],"answer":1,"explanation":"Third-year interest is 0.121P and fourth-year interest 0.1331P, so the excess is 0.0121P = 484, giving P = ₹40,000.","difficulty":"hard","questionHi":"10% वार्षिक चक्रवृद्धि ब्याज पर चौथे वर्ष का ब्याज तीसरे वर्ष के ब्याज से ₹484 अधिक है। मूलधन क्या है?","optionsHi":["₹44,000","₹40,000","₹48,400","₹36,000"],"explanationHi":"तीसरे वर्ष का ब्याज 0.121P और चौथे वर्ष का 0.1331P है, अतः अधिकता 0.0121P = 484, जिससे P = ₹40,000।","subtopic":"year-wise-interest","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-198","question":"At compound interest the interest for the third year is ₹2,420 and for the fourth year ₹2,662. What is the total interest for the first two years?","options":["₹4,000","₹4,620","₹3,630","₹4,200"],"answer":3,"explanation":"2,662/2,420 = 1.1 so r = 10%. Third-year interest = P × 1.21 × 0.1 = 2,420 gives P = 20,000, and two-year interest is 20,000 × 0.21 = ₹4,200.","difficulty":"hard","questionHi":"चक्रवृद्धि ब्याज पर तीसरे वर्ष का ब्याज ₹2,420 और चौथे वर्ष का ₹2,662 है। पहले दो वर्षों का कुल ब्याज क्या है?","optionsHi":["₹4,000","₹4,620","₹3,630","₹4,200"],"explanationHi":"2,662/2,420 = 1.1 अतः r = 10%। तीसरे वर्ष का ब्याज = P × 1.21 × 0.1 = 2,420 से P = 20,000, और दो वर्ष का ब्याज 20,000 × 0.21 = ₹4,200।","subtopic":"year-wise-interest","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-199","question":"At 20% per annum, the compound interest (compounded half-yearly) on a sum for one year exceeds the simple interest by ₹250. What is the sum?","options":["₹20,000","₹50,000","₹25,000","₹12,500"],"answer":2,"explanation":"Half-yearly gives 1.1² − 1 = 0.21 against simple 0.20, so the excess is 0.01P = 250 and P = ₹25,000.","difficulty":"hard","questionHi":"20% वार्षिक दर पर किसी धनराशि का एक वर्ष का चक्रवृद्धि ब्याज (अर्धवार्षिक संयोजन) साधारण ब्याज से ₹250 अधिक है। वह धनराशि क्या है?","optionsHi":["₹20,000","₹50,000","₹25,000","₹12,500"],"explanationHi":"अर्धवार्षिक से 1.1² − 1 = 0.21 मिलता है जबकि साधारण से 0.20, अतः अधिकता 0.01P = 250 और P = ₹25,000।","subtopic":"ci-si-difference","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-200","question":"At 10% per annum the difference between compound interest and simple interest on a sum for 4 years is ₹641. What is the sum?","options":["₹10,000","₹6,410","₹8,000","₹12,000"],"answer":0,"explanation":"CI factor is 1.1⁴ − 1 = 0.4641 and SI factor is 0.4, so the difference is 0.0641P = 641 and P = ₹10,000.","difficulty":"very-hard","questionHi":"10% वार्षिक दर पर किसी धनराशि के 4 वर्ष के चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर ₹641 है। वह धनराशि क्या है?","optionsHi":["₹10,000","₹6,410","₹8,000","₹12,000"],"explanationHi":"चक्रवृद्धि गुणक 1.1⁴ − 1 = 0.4641 और साधारण ब्याज गुणक 0.4 है, अतः अंतर 0.0641P = 641 और P = ₹10,000।","subtopic":"ci-si-difference","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-201","question":"A town's population rises by 10% in one year and then falls by x% in the next year, so that over the two years it has a net fall of 1%. What is x?","options":["11%","9%","10.9%","10%"],"answer":3,"explanation":"1.1 × (1 − x/100) = 0.99 gives 1 − x/100 = 0.9, so x = 10%. A rise and a fall of 10% leave a net fall of 1%, not zero.","difficulty":"moderate","questionHi":"एक कस्बे की जनसंख्या एक वर्ष में 10% बढ़ती है और अगले वर्ष x% घटती है, जिससे दो वर्षों में उसमें कुल 1% की कमी आती है। x का मान क्या है?","optionsHi":["11%","9%","10.9%","10%"],"explanationHi":"1.1 × (1 − x/100) = 0.99 से 1 − x/100 = 0.9, अतः x = 10%। 10% वृद्धि और 10% कमी से कुल 1% की कमी आती है, शून्य नहीं।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-202","question":"What is the compound interest on ₹20,000 for 3 years if the rates for the first, second and third year are 10%, 15% and 20% respectively?","options":["₹9,000","₹10,360","₹10,417.50","₹10,800"],"answer":1,"explanation":"Amount = 20,000 × 1.1 × 1.15 × 1.2 = ₹30,360, so the interest is ₹10,360. Using a flat 15% for 3 years gives ₹10,417.50, which is not the same.","difficulty":"hard","questionHi":"यदि पहले, दूसरे और तीसरे वर्ष की दरें क्रमशः 10%, 15% और 20% हों, तो ₹20,000 पर 3 वर्ष का चक्रवृद्धि ब्याज क्या है?","optionsHi":["₹9,000","₹10,360","₹10,417.50","₹10,800"],"explanationHi":"मिश्रधन = 20,000 × 1.1 × 1.15 × 1.2 = ₹30,360, अतः ब्याज ₹10,360 है। 3 वर्ष के लिए एकसमान 15% लेने पर ₹10,417.50 आता है, जो समान नहीं है।","subtopic":"varying-rates","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-203","question":"Assertion (A): For a positive rate and a period of 2 years, compound interest is greater than simple interest on the same sum. Reason (R): In compound interest, the interest of the first year itself earns interest in the second year.","options":["Both A and R are true but R does not explain A","Both A and R are true and R explains A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"The extra amount in CI over SI is exactly the interest earned on the first year's interest, Pr², so both statements are true and R is the reason for A.","difficulty":"moderate","questionHi":"अभिकथन (A): धनात्मक दर और 2 वर्ष की अवधि के लिए, उसी धनराशि पर चक्रवृद्धि ब्याज साधारण ब्याज से अधिक होता है। कारण (R): चक्रवृद्धि ब्याज में पहले वर्ष का ब्याज स्वयं दूसरे वर्ष में ब्याज अर्जित करता है।","optionsHi":["A और R दोनों सत्य हैं परंतु R, A की व्याख्या नहीं करता","A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"सा.ब्या. की तुलना में चक्रवृद्धि ब्याज में अतिरिक्त राशि ठीक पहले वर्ष के ब्याज पर अर्जित ब्याज Pr² होती है, अतः दोनों कथन सत्य हैं और R ही A का कारण है।","subtopic":"annual-compounding","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-204","question":"₹10,000 invested for one year with interest compounded half-yearly earns a compound interest of ₹1,025. What is the rate of interest per annum?","options":["10.25%","5%","20.5%","10%"],"answer":3,"explanation":"(1 + r/200)² = 1.1025 gives r/200 = 0.05, so the nominal rate is 10% per annum. The 10.25% option is the effective rate, not the stated rate.","difficulty":"hard","questionHi":"₹10,000 को एक वर्ष के लिए अर्धवार्षिक संयोजन वाले ब्याज पर निवेश करने पर ₹1,025 चक्रवृद्धि ब्याज मिलता है। वार्षिक ब्याज दर क्या है?","optionsHi":["10.25%","5%","20.5%","10%"],"explanationHi":"(1 + r/200)² = 1.1025 से r/200 = 0.05, अतः नाममात्र वार्षिक दर 10% है। 10.25% प्रभावी दर है, घोषित दर नहीं।","subtopic":"half-yearly-quarterly","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-205","question":"Plan X pays 10% per annum for the first six months and 20% per annum for the next six months, with interest compounded at the end of each half-year. Plan Y pays 15% per annum compounded annually. How much more does Plan X yield on ₹40,000 in one year?","options":["₹200","₹0","₹100","₹400"],"answer":0,"explanation":"Plan X: 40,000 × 1.05 × 1.10 = ₹46,200. Plan Y: 40,000 × 1.15 = ₹46,000. The difference is ₹200, even though the average of 10% and 20% is 15%.","difficulty":"very-hard","questionHi":"योजना X पहले छह महीने 10% वार्षिक और अगले छह महीने 20% वार्षिक देती है, जिसमें ब्याज प्रत्येक छमाही के अंत में संयोजित होता है। योजना Y 15% वार्षिक दर देती है, वार्षिक संयोजन के साथ। ₹40,000 पर एक वर्ष में योजना X कितना अधिक देती है?","optionsHi":["₹200","₹0","₹100","₹400"],"explanationHi":"योजना X: 40,000 × 1.05 × 1.10 = ₹46,200। योजना Y: 40,000 × 1.15 = ₹46,000। अंतर ₹200 है, यद्यपि 10% और 20% का औसत 15% है।","subtopic":"varying-rates","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-206","question":"₹8,000 becomes ₹9,261 in 1½ years when interest is compounded half-yearly. What is the rate of interest per annum?","options":["5%","15.76%","10%","20%"],"answer":2,"explanation":"9,261/8,000 = 1.157625 = 1.05³, so the half-yearly rate is 5% and the annual rate is 10%. The 5% option forgets to double the half-yearly rate.","difficulty":"hard","questionHi":"अर्धवार्षिक संयोजन पर ₹8,000, 1½ वर्ष में ₹9,261 हो जाते हैं। वार्षिक ब्याज दर क्या है?","optionsHi":["5%","15.76%","10%","20%"],"explanationHi":"9,261/8,000 = 1.157625 = 1.05³, अतः छमाही दर 5% और वार्षिक दर 10% है। 5% वाला विकल्प छमाही दर को दोगुना करना भूल जाता है।","subtopic":"rate-from-amounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-207","question":"At simple interest a sum doubles in 10 years. At the same rate of interest compounded annually, what is the compound interest on ₹5,000 for 2 years?","options":["₹1,000","₹1,100","₹1,025","₹1,050"],"answer":3,"explanation":"Doubling in 10 years at SI means 10% per annum. Compound interest = 5,000 × (1.21 − 1) = ₹1,050.","difficulty":"hard","questionHi":"साधारण ब्याज पर कोई धनराशि 10 वर्ष में दोगुनी हो जाती है। उसी दर पर वार्षिक संयोजन के साथ ₹5,000 का 2 वर्ष का चक्रवृद्धि ब्याज क्या है?","optionsHi":["₹1,000","₹1,100","₹1,025","₹1,050"],"explanationHi":"साधारण ब्याज पर 10 वर्ष में दोगुना होने का अर्थ है 10% वार्षिक दर। चक्रवृद्धि ब्याज = 5,000 × (1.21 − 1) = ₹1,050।","subtopic":"times-the-sum","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-208","question":"For 2 years at the same rate, the ratio of compound interest to simple interest on a sum is 41 : 40. What is the rate of interest per annum?","options":["2.5%","5%","4%","10%"],"answer":1,"explanation":"CI : SI = (2r + r²) : 2r = (2 + r)/2 = 41/40, so r = 0.05, i.e. 5%.","difficulty":"hard","questionHi":"एक ही दर पर 2 वर्ष के लिए किसी धनराशि के चक्रवृद्धि ब्याज और साधारण ब्याज का अनुपात 41 : 40 है। वार्षिक ब्याज दर क्या है?","optionsHi":["2.5%","5%","4%","10%"],"explanationHi":"चक्रवृद्धि : साधारण = (2r + r²) : 2r = (2 + r)/2 = 41/40, अतः r = 0.05, अर्थात् 5%।","subtopic":"ci-si-difference","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ci-209","question":"A town's population grows 20% in each of the first two years and then falls 10% in each of the next two years. If it is now 1,16,640, what was the population four years ago?","options":["1,20,000","1,08,000","1,00,000","90,000"],"answer":2,"explanation":"Net factor = 1.2² × 0.9² = 1.44 × 0.81 = 1.1664, so the original population = 1,16,640/1.1664 = 1,00,000.","difficulty":"very-hard","questionHi":"एक कस्बे की जनसंख्या पहले दो वर्षों में प्रत्येक में 20% बढ़ती है और फिर अगले दो वर्षों में प्रत्येक में 10% घटती है। यदि वह अब 1,16,640 है, तो चार वर्ष पहले जनसंख्या कितनी थी?","optionsHi":["1,20,000","1,08,000","1,00,000","90,000"],"explanationHi":"कुल गुणक = 1.2² × 0.9² = 1.44 × 0.81 = 1.1664, अतः मूल जनसंख्या = 1,16,640/1.1664 = 1,00,000।","subtopic":"population-depreciation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

export default questions;
